--- index.html
+++ index.html
@@ -1017,7 +1017,858 @@
 </div>

 <script>
 /* !!! APP CODE — TODESFUNK / ORBITAL 9 — BANDOS7 !!! */
+'use strict';
+/* ============================================================
+   0. CORE UTILITIES
+   ============================================================ */
+const $ = (sel, root = document) => root.querySelector(sel);
+const $$ = (sel, root = document) => Array.from(root.querySelectorAll(sel));
+const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
+const lerp = (a, b, t) => a + (b - a) * t;
+const ease = t => 1 - Math.pow(1 - t, 3);
+const TAU = Math.PI * 2;
+const STORE = {
+  settings: 'todesfunk.settings.v2',
+  save: 'todesfunk.campaign.v2',
+  ranking: 'todesfunk.ranking.v2',
+  archive: 'todesfunk.archive.v2'
+};
+function hash(n) {
+  n = (n ^ 61) ^ (n >>> 16); n = n + (n << 3); n = n ^ (n >>> 4);
+  n = Math.imul(n, 0x27d4eb2d); n = n ^ (n >>> 15);
+  return (n >>> 0) / 4294967296;
+}
+function mulberry32(seed) {
+  let a = seed >>> 0;
+  return function () {
+    a |= 0; a = (a + 0x6D2B79F5) | 0;
+    let t = Math.imul(a ^ (a >>> 15), 1 | a);
+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+  };
+}
+function pick(arr, rng = Math.random) { return arr[Math.floor(rng() * arr.length)]; }
+function shuffle(arr, rng = Math.random) {
+  const a = arr.slice();
+  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
+  return a;
+}
+function esc(s) {
+  return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
+}
+function fmtNum(n) { return Math.round(n).toLocaleString('de-DE'); }
+function fmtTime(sec) {
+  sec = Math.max(0, Math.round(sec));
+  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
+  return (h > 0 ? h + ':' : '') + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
+}
+function fmtReal(ms) {
+  const s = Math.floor(ms / 1000), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
+  return (h > 0 ? h + 'h ' : '') + m + 'm';
+}
+function readJSON(key, fallback) {
+  try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : fallback; }
+  catch (e) { return fallback; }
+}
+function writeJSON(key, value) {
+  try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* storage can be unavailable */ }
+}
+function vibrate(pattern) {
+  if (!settings.haptics) return;
+  try { if (navigator.vibrate) navigator.vibrate(pattern); } catch (e) {}
+}
+function flashFX(kind = 'flash') {
+  const el = kind === 'glitch' ? $('#fx-glitch') : $('#fx-flash');
+  if (!el) return;
+  el.classList.remove('on'); void el.offsetWidth; el.classList.add('on');
+}
+function svgAvatar(gender, seed = 1) {
+  const hair = gender === 'f'
+    ? '<path d="M25 20c-9 1-14 9-13 20 2 11 8 15 8 15l-2-19 8-7 8 7-2 18s9-7 10-18c1-12-5-17-17-16z" fill="#092a32" stroke="#65f4ff" stroke-width="1"/>'
+    : '<path d="M23 14c-7 1-11 6-10 13 1 6 4 8 4 8l-1-10 7-3 8 3-1 9s5-4 5-11c0-8-5-10-12-9z" fill="#092a32" stroke="#65f4ff" stroke-width="1"/>';
+  return `<svg viewBox="0 0 64 76" aria-hidden="true">
+    <defs><linearGradient id="ag${seed}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="rgba(113,246,255,.24)"/><stop offset="1" stop-color="rgba(113,246,255,.04)"/></linearGradient></defs>
+    <rect width="64" height="76" fill="url(#ag${seed})"/>
+    <path d="M14 76c0-19 7-29 18-29s18 10 18 29z" fill="#061a21" stroke="rgba(113,246,255,.55)" stroke-width=".8"/>
+    <path d="M25 45h14v12H25z" fill="#061a21" stroke="rgba(113,246,255,.35)" stroke-width=".7"/>
+    <ellipse cx="32" cy="30" rx="13" ry="17" fill="#061a21" stroke="rgba(113,246,255,.65)" stroke-width=".8"/>
+    ${hair}
+    <path d="M28 31h8M29 37h6" stroke="rgba(113,246,255,.7)" stroke-width=".8" stroke-linecap="round"/>
+    <path d="M16 76V58M48 76V58" stroke="rgba(255,191,105,.26)" stroke-width=".7"/>
+    <rect width="64" height="76" fill="none" stroke="rgba(113,246,255,.18)"/>
+  </svg>`;
+}
+
+/* ============================================================
+   1. SETTINGS
+   ============================================================ */
+const DEFAULT_SETTINGS = {
+  quality: 'high',
+  theme: 'swipe',
+  input: 'auto',
+  accent: 'cyan',
+  textSize: 'normal',
+  sound: true,
+  music: 0.55,
+  sfx: 0.8,
+  haptics: true,
+  notifications: true,
+  systemNotifications: false,
+  reducedMotion: false,
+  typewriter: true,
+  timePressure: true,
+  realtime: 'short',
+  operator: 'OPERATOR',
+  defaultDifficulty: 'normal',
+  autoFire: true
+};
+let settings = Object.assign({}, DEFAULT_SETTINGS, readJSON(STORE.settings, {}));
+let archive = readJSON(STORE.archive, {
+  runs: 0, rescued: 0, dead: 0, bestAct: 0, endings: [], achievements: [],
+  totalChoices: 0, sandboxKills: 0, sandboxBest: 0, themesUsed: [], survivors: []
+});
+archive.endings = archive.endings || []; archive.achievements = archive.achievements || [];
+archive.themesUsed = archive.themesUsed || []; archive.survivors = archive.survivors || [];
+let ranking = readJSON(STORE.ranking, { campaign: [], sandbox: [] });
+ranking.campaign = ranking.campaign || []; ranking.sandbox = ranking.sandbox || [];
+let savedRun = readJSON(STORE.save, null);
+const ACCENTS = {
+  cyan: { hex: '#71f6ff', rgb: '113,246,255', dim: '#1d7f8c' },
+  amber: { hex: '#ffbf69', rgb: '255,191,105', dim: '#8b6a2d' },
+  magenta: { hex: '#ff6ed0', rgb: '255,110,208', dim: '#85336c' },
+  lime: { hex: '#a9ff72', rgb: '169,255,114', dim: '#4d842f' }
+};
+function saveSettings() { writeJSON(STORE.settings, settings); }
+function applySettings() {
+  const a = ACCENTS[settings.accent] || ACCENTS.cyan;
+  const root = document.documentElement;
+  root.style.setProperty('--accent', a.hex);
+  root.style.setProperty('--accent-rgb', a.rgb);
+  root.style.setProperty('--accent-dim', a.dim);
+  root.classList.remove('quality-low', 'quality-balanced', 'quality-high', 'quality-ultra');
+  root.classList.add('quality-' + settings.quality);
+  root.classList.remove('text-small', 'text-normal', 'text-large');
+  root.classList.add('text-' + settings.textSize);
+  root.classList.toggle('reduce-motion', !!settings.reducedMotion);
+  const app = $('#app');
+  app.dataset.quality = settings.quality;
+  app.classList.remove('theme-swipe', 'theme-terminal', 'theme-minimal', 'theme-edge', 'theme-radial', 'theme-dual', 'theme-deck');
+  app.classList.add('theme-' + settings.theme);
+  $('#btn-audio').classList.toggle('muted', !settings.sound);
+  Scene && Scene.refreshQuality && Scene.refreshQuality();
+}
+function updateSetting(key, value) {
+  settings[key] = value;
+  applySettings();
+  saveSettings();
+  if (key === 'theme') {
+    if (!archive.themesUsed.includes(value)) {
+      archive.themesUsed.push(value);
+      saveArchive(); checkAchievements();
+    }
+  }
+  if (window.Audio1) Audio1.updateVolumes();
+  renderOptions();
+}
+
+/* ============================================================
+   2. AUDIO — fully synthesized, no external assets
+   ============================================================ */
+class AudioEngine {
+  constructor() {
+    this.ctx = null; this.master = null; this.musicGain = null; this.sfxGain = null;
+    this.mode = 'menu'; this.started = false; this.nodes = []; this.timer = null; this.pulseTimer = null;
+    this.noiseBuffer = null;
+  }
+  init() {
+    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
+    const AC = window.AudioContext || window.webkitAudioContext;
+    if (!AC) return;
+    try {
+      this.ctx = new AC();
+      this.master = this.ctx.createGain();
+      this.master.gain.value = settings.sound ? 0.9 : 0;
+      this.master.connect(this.ctx.destination);
+      this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = settings.music * 0.24; this.musicGain.connect(this.master);
+      this.sfxGain = this.ctx.createGain(); this.sfxGain.gain.value = settings.sfx * 0.5; this.sfxGain.connect(this.master);
+      this.noiseBuffer = this.makeNoise(2.4);
+      this.started = true;
+      this.startAmbient(this.mode);
+    } catch (e) { console.warn('Audio unavailable', e); }
+  }
+  makeNoise(seconds) {
+    const len = Math.floor(this.ctx.sampleRate * seconds);
+    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
+    const d = buf.getChannelData(0);
+    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
+    return buf;
+  }
+  updateVolumes() {
+    if (!this.ctx) return;
+    this.master.gain.setTargetAtTime(settings.sound ? 0.9 : 0, this.ctx.currentTime, 0.08);
+    this.musicGain.gain.setTargetAtTime(settings.music * 0.24, this.ctx.currentTime, 0.08);
+    this.sfxGain.gain.setTargetAtTime(settings.sfx * 0.5, this.ctx.currentTime, 0.06);
+  }
+  tone(freq, dur, type = 'sine', gain = 0.2, slide = 0, delay = 0, dest = null) {
+    if (!this.ctx || !settings.sound) return;
+    const t = this.ctx.currentTime + delay;
+    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
+    o.type = type; o.frequency.setValueAtTime(Math.max(20, freq), t);
+    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
+    g.gain.setValueAtTime(0.0001, t);
+    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.012);
+    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
+    o.connect(g); g.connect(dest || this.sfxGain);
+    o.start(t); o.stop(t + dur + 0.03);
+  }
+  noise(dur = 0.2, gain = 0.2, freq = 800, q = 1, delay = 0) {
+    if (!this.ctx || !settings.sound || !this.noiseBuffer) return;
+    const t = this.ctx.currentTime + delay;
+    const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuffer; src.loop = true;
+    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = freq; f.Q.value = q;
+    const g = this.ctx.createGain();
+    g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
+    src.connect(f); f.connect(g); g.connect(this.sfxGain);
+    src.start(t); src.stop(t + dur + 0.02);
+  }
+  sfx(name) {
+    if (!this.ctx || !settings.sound) return;
+    switch (name) {
+      case 'click': this.tone(620, .06, 'triangle', .1, -180); break;
+      case 'back': this.tone(330, .09, 'triangle', .08, 100); break;
+      case 'msg': this.tone(880, .1, 'sine', .07); this.tone(1320, .16, 'sine', .045, 0, .08); break;
+      case 'notify': this.tone(523, .1, 'triangle', .08); this.tone(784, .12, 'triangle', .07, 0, .08); this.tone(1046, .24, 'sine', .05, 0, .2); break;
+      case 'alarm': this.tone(180, .4, 'sawtooth', .08, 90); this.tone(240, .28, 'square', .035, -70, .42); break;
+      case 'success': [523, 659, 784, 1046].forEach((f, i) => this.tone(f, .45, 'sine', .075, 0, i * .09)); break;
+      case 'error': this.tone(110, .3, 'sawtooth', .1, -35); this.noise(.18, .08, 300, .8); break;
+      case 'death': this.tone(90, 1.6, 'sawtooth', .14, -55); this.noise(1.1, .05, 170, .4); break;
+      case 'gun': this.noise(.055, .12, 1600, 1.2); this.tone(180, .06, 'square', .05, -60); break;
+      case 'rail': this.tone(740, .18, 'sawtooth', .09, -500); this.noise(.12, .08, 2400, 1.6); break;
+      case 'hit': this.noise(.06, .08, 900, 2); break;
+      case 'explode': this.noise(.45, .22, 280, .7); this.tone(65, .4, 'sawtooth', .12, -30); break;
+      case 'pickup': this.tone(660, .09, 'sine', .07, 140); this.tone(990, .18, 'sine', .05, 180, .07); break;
+      case 'type': this.tone(1300 + Math.random() * 500, .012, 'square', .012); break;
+      case 'glitch': this.noise(.11, .05, 2800, .8); this.tone(75, .13, 'square', .025, 700); break;
+      case 'act': [110, 165, 220, 330].forEach((f, i) => this.tone(f, .8, 'sine', .06, 0, i * .12)); break;
+      case 'heart': this.tone(52, .14, 'sine', .16); this.tone(48, .12, 'sine', .1, 0, .18); break;
+      case 'heal': this.tone(420, .18, 'sine', .07, 240); this.tone(880, .35, 'sine', .045, 220, .1); break;
+      default: this.tone(500, .05, 'sine', .04);
+    }
+  }
+  stopAmbient() {
+    if (this.timer) { clearInterval(this.timer); this.timer = null; }
+    if (this.pulseTimer) { clearInterval(this.pulseTimer); this.pulseTimer = null; }
+    this.nodes.forEach(n => { try { n.stop(0); } catch (e) {} try { n.disconnect(); } catch (e) {} });
+    this.nodes = [];
+  }
+  startAmbient(mode) {
+    this.mode = mode;
+    if (!this.ctx || !settings.sound) return;
+    this.stopAmbient();
+    const ctx = this.ctx;
+    const base = mode === 'combat' ? 46 : mode === 'campaign' ? 38 : 32;
+    const root = ctx.createGain(); root.gain.value = 0.0001; root.connect(this.musicGain);
+    root.gain.exponentialRampToValueAtTime(mode === 'combat' ? .22 : .15, ctx.currentTime + 1.6);
+    this.nodes.push(root);
+    const freqs = [base, base * 1.5, base * 2, base * 2.997, base * 4.01];
+    freqs.forEach((f, i) => {
+      const o = ctx.createOscillator(); const g = ctx.createGain();
+      o.type = i === 0 ? 'sawtooth' : i < 3 ? 'triangle' : 'sine';
+      o.frequency.value = f; o.detune.value = (i - 2) * (mode === 'combat' ? 8 : 3);
+      g.gain.value = i === 0 ? .16 : .05 / (i + .4);
+      const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = mode === 'combat' ? 480 : 260; lp.Q.value = 1.2;
+      o.connect(g); g.connect(lp); lp.connect(root); o.start(); this.nodes.push(o, g, lp);
+    });
+    if (mode !== 'combat') {
+      const o = ctx.createOscillator(); const g = ctx.createGain();
+      o.type = 'sine'; o.frequency.value = 192 - (mode === 'campaign' ? 10 : 0);
+      g.gain.value = .028; o.connect(g); g.connect(root); o.start(); this.nodes.push(o, g);
+    }
+    if (this.noiseBuffer) {
+      const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer; src.loop = true;
+      const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = mode === 'combat' ? 1200 : 700; f.Q.value = .35;
+      const g = ctx.createGain(); g.gain.value = mode === 'combat' ? .035 : .05;
+      src.connect(f); f.connect(g); g.connect(this.musicGain); src.start(); this.nodes.push(src, f, g);
+    }
+    let step = 0;
+    const chordSets = mode === 'combat'
+      ? [[0, 1, 2.997], [0, 1.335, 2], [0, 1.189, 2.378], [0, 1.498, 2.245]]
+      : [[0, 1.5, 2.997], [0, 1.335, 2.245], [0, 1.189, 2.997], [0, 1.414, 2.378]];
+    this.timer = setInterval(() => {
+      if (!settings.sound || !this.ctx) return;
+      const set = chordSets[step % chordSets.length]; step++;
+      set.forEach((mult, i) => {
+        const o = ctx.createOscillator(); const g = ctx.createGain();
+        o.type = i === 0 ? 'triangle' : 'sine'; o.frequency.value = (mode === 'combat' ? 92 : 74) * mult;
+        const t = ctx.currentTime;
+        g.gain.setValueAtTime(0.0001, t);
+        g.gain.exponentialRampToValueAtTime(mode === 'combat' ? .025 : .018, t + .55);
+        g.gain.exponentialRampToValueAtTime(0.0001, t + (mode === 'combat' ? 2.4 : 5.8));
+        o.connect(g); g.connect(this.musicGain); o.start(t); o.stop(t + 6.2);
+      });
+    }, mode === 'combat' ? 2500 : 7200);
+    if (mode === 'combat') {
+      this.pulseTimer = setInterval(() => {
+        if (!settings.sound) return;
+        this.tone(60, .16, 'sine', .08, -20);
+        if (Math.random() > .55) this.noise(.06, .022, 2200, 1.2);
+      }, 560);
+    } else if (mode === 'campaign') {
+      this.pulseTimer = setInterval(() => {
+        if (!settings.sound) return;
+        this.tone(55, .5, 'sine', .035, -12);
+      }, 6200);
+    }
+  }
+  setMode(mode) {
+    if (this.mode === mode && this.started) return;
+    this.mode = mode;
+    if (this.ctx) this.startAmbient(mode);
+  }
+  setEnabled(on) {
+    if (on) { this.init(); if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); }
+    settings.sound = on;
+    if (this.master) this.master.gain.setTargetAtTime(on ? .9 : 0, this.ctx.currentTime, .08);
+  }
+}
+const Audio1 = new AudioEngine();
+
+/* ============================================================
+   3. UI HELPERS / NAVIGATION
+   ============================================================ */
+const App = { screen: 'menu', previous: 'menu', booted: false, activeTheme: 'swipe', activeModal: null };
+let Scene = null;
+const screenIds = ['menu', 'campaign', 'sandbox', 'ranking', 'archive', 'options', 'credits', 'ending'];
+function showScreen(name, opts = {}) {
+  const target = $('#screen-' + name);
+  if (!target) return;
+  $$('.screen').forEach(s => s.classList.remove('active'));
+  target.classList.add('active');
+  App.previous = App.screen === name ? App.previous : App.screen;
+  App.screen = name;
+  if (!opts.silent) Audio1.sfx('click');
+  if (name === 'menu') { Audio1.setMode('menu'); refreshMenuState(); }
+  if (name === 'campaign') Audio1.setMode('campaign');
+  if (name === 'sandbox') Audio1.setMode('menu');
+  if (name === 'ending') Audio1.setMode('campaign');
+  const stageModes = { campaign: 'campaign', sandbox: 'sandbox', ending: 'campaign' };
+  if (Scene) Scene.setMode(stageModes[name] || 'menu');
+  closeModal(true);
+}
+function toast(text, type = '') {
+  const host = $('#toasts');
+  const el = document.createElement('div');
+  el.className = 'toast ' + type;
+  el.textContent = text;
+  host.appendChild(el);
+  setTimeout(() => { el.style.opacity = '0'; el.style.transition = 'opacity .25s'; setTimeout(() => el.remove(), 260); }, 2600);
+  while (host.children.length > 3) host.firstElementChild.remove();
+}
+function openModal(htmlOfCard, opts = {}) {
+  const modal = $('#modal');
+  $('#modal-card').innerHTML = htmlOfCard;
+  modal.classList.add('open'); modal.setAttribute('aria-hidden', 'false');
+  App.activeModal = opts.type || true;
+  if (!opts.silent) Audio1.sfx('click');
+  if (opts.onOpen) opts.onOpen($('#modal-card'));
+}
+function closeModal(silent = false) {
+  const modal = $('#modal');
+  if (!modal.classList.contains('open')) return;
+  modal.classList.remove('open'); modal.setAttribute('aria-hidden', 'true');
+  App.activeModal = null;
+  if (!silent) Audio1.sfx('back');
+  setTimeout(() => { if (!modal.classList.contains('open')) $('#modal-card').innerHTML = ''; }, 260);
+}
+function saveArchive() { writeJSON(STORE.archive, archive); }
+function checkAchievements() {
+  const unlock = id => {
+    if (!archive.achievements.includes(id)) {
+      archive.achievements.push(id);
+      saveArchive();
+      const def = ACHIEVEMENTS.find(a => a.id === id);
+      if (def && App.booted) { toast('ERRUNGENSCHAFT · ' + def.name, 'good'); Audio1.sfx('success'); }
+    }
+  };
+  if (archive.rescued >= 1) unlock('first_rescue');
+  if (archive.dead >= 1) unlock('first_death');
+  if (archive.runs >= 5) unlock('five_runs');
+  if (archive.endings.length >= 3) unlock('three_endings');
+  if (archive.endings.length >= 8) unlock('eight_endings');
+  if (archive.sandboxKills >= 10) unlock('ten_kills');
+  if (archive.sandboxKills >= 100) unlock('hundred_kills');
+  if (archive.themesUsed.length >= 5) unlock('theme_master');
+  if (archive.survivors.length >= 6) unlock('all_faces');
+  if (archive.runs >= 1) unlock('first_signal');
+}
+
+/* ============================================================
+   4. SCENE RENDERER — procedural city / campaign cinematics
+   ============================================================ */
+class SceneRenderer {
+  constructor(canvas) {
+    this.canvas = canvas;
+    this.ctx = canvas.getContext('2d', { alpha: false });
+    this.w = 390; this.h = 694; this.dpr = 1;
+    this.mode = 'menu'; this.t = 0; this.last = 0;
+    this.menu = { stars: [], rain: [], buildingsFar: [], buildingsMid: [], buildingsNear: [], drones: [], signs: [], flashes: [] };
+    this.campaign = { particles: [], sparks: [], rain: [] };
+    this.shake = 0;
+    this.quality = this.readQuality();
+    this.resize();
+    if (window.ResizeObserver) new ResizeObserver(() => this.resize()).observe(canvas.parentElement || canvas);
+    window.addEventListener('resize', () => this.resize());
+    this.loop = this.loop.bind(this);
+    requestAnimationFrame(this.loop);
+  }
+  readQuality() {
+    switch (settings.quality) {
+      case 'low': return { dpr: 1, rain: 24, stars: 40, particles: 30, glow: false, extras: false, scans: false, city: 0.55 };
