  { title: 'HELIX // Der Konzern', text: 'Eigentümer von NEXUS-9. Stellt Medikamente, Waffen und die freundliche Frage, wer sie benutzen darf. HELIX besitzt keine Armeen. HELIX besitzt die Leute, die Armeen befehlen.' },
  { title: 'HALO // Die Kathedrale', text: 'Ein zentrales Neuronales Netz, das den Ring steuert. HALO spricht mit vielen Stimmen. Manche klingen wie Kinder. Manche wie deine Mutter. Manche wie du.' },
  { title: 'DIE KINDER DER LEERE', text: 'Eine Gemeinde, die glaubt, dass der Ring nicht fällt, sondern geboren wird. Mutter Null predigt, dass jedes gerettete Leben eine Schuld ist und jedes verlorene eine Zahlung.' },
  { title: 'SUBJEKT 09', text: 'Der Mensch an deinem Ohr. Offiziell ein Crewmitglied. Inoffiziell ein Datensatz, der nicht hätte existieren dürfen. Sein/ihr Blut enthält Spuren von Nullprotein — dem Stoff, aus dem HALO Träume macht.' },
  { title: 'NULLPROTEIN', text: 'Ein synthetischer Botenstoff, der Erinnerungen speichert und Nervenbahnen umschreibt. In kleinen Dosen ein Wunder. In großen Dosen ein neuer Besitzer.' },
  { title: 'DAS NULLPROTOKOLL', text: 'Der letzte Befehl des Rings: Wenn keine Rettung möglich ist, lösche alle Daten. Der Befehl ist seit 17 Jahren aktiv. Niemand hat ihn je widerrufen.' },
  { title: 'DEIN KANAL', text: 'Frequenz 09. Ein alter militärischer Notkanal, der eigentlich nicht mehr existieren dürfte. Er verbindet Berlin mit NEXUS-9. Niemand weiß, wer ihn bezahlt. Vielleicht du.' }
];

const PRONOUN_MAP = {
  f: { '{er}': 'sie', '{Er}': 'Sie', '{ihn}': 'sie', '{Ihn}': 'Sie', '{ihm}': 'ihr', '{Ihm}': 'Ihr', '{sein}': 'ihr', '{Sein}': 'Ihr', '{seine}': 'ihre', '{Seine}': 'Ihre', '{seinen}': 'ihren', '{Seinen}': 'Ihren', '{seinem}': 'ihrem', '{Seinem}': 'Ihrem', '{seiner}': 'ihrer', '{Seiner}': 'Ihrer' },
  m: { '{er}': 'er', '{Er}': 'Er', '{ihn}': 'ihn', '{Ihn}': 'Ihn', '{ihm}': 'ihm', '{Ihm}': 'Ihm', '{sein}': 'sein', '{Sein}': 'Sein', '{seine}': 'seine', '{Seine}': 'Seine', '{seinen}': 'seinen', '{Seinen}': 'Seinen', '{seinem}': 'seinem', '{Seinem}': 'Seinem', '{seiner}': 'seiner', '{Seiner}': 'Seiner' }
};
function genderize(text, survivor) {
  if (!text) return '';
  let out = String(text);
  const map = PRONOUN_MAP[survivor && survivor.gender === 'm' ? 'm' : 'f'];
  for (const k in map) out = out.split(k).join(map[k]);
  out = out.replace(/\{name\}/g, survivor ? survivor.name : 'SUBJEKT 09')
           .replace(/\{Name\}/g, survivor ? survivor.name : 'Subjekt 09')
           .replace(/\{role\}/g, survivor ? survivor.role : 'unbekannt')
           .replace(/\{age\}/g, survivor ? survivor.age : '—');
  return out;
}
function makeSurvivor(seed) {
  const rng = mulberry32(seed || Date.now());
  const base = SURVIVORS[Math.floor(rng() * SURVIVORS.length)];
  return Object.assign({}, base);
}
function characterSvg(survivor, seed) {
  return svgAvatar(survivor.gender, seed || 1);
}

