+  impossible: { key: 'impossible', name: 'UNMÖGLICH', desc: 'Nur ein Mensch mit einer verdammt guten Stimme kommt hier lebend raus.', loss: 2.15, timer: .5, vit: 68, o2: 58, tr: 28, med: 0, score: 2.2, risk: 'SUIZIDAL', riskClass: 'danger', extra: 'Keine Safety-Netze. Kein Zurück.' }
+};
+const CONTROL_THEMES = [
+  { id: 'swipe', name: 'Neon Swipe', desc: 'Karten antippen oder in eine Richtung wischen. Ein Finger.', hint: 'WISCHEN ODER TIPPEN', visual: [9, 15, 22] },
+  { id: 'terminal', name: 'Terminal', desc: 'Monochromes Tastatur-Layout. Große Zeilen, harte Kanten.', hint: 'A / B / C ANTIPPEN', visual: [24, 24, 24] },
+  { id: 'radial', name: 'Holo-Radial', desc: 'Drei Optionen kreisen um deine Entscheidung. Kurze Wege.', hint: 'HOLO-KNOTEN ANTIPPEN', visual: [8, 20, 8] },
+  { id: 'dual', name: 'Zwei-Finger-Dial', desc: 'Mit zwei Fingern horizontal ziehen. Loslassen bestätigt.', hint: '2 FINGER ZIEHEN · LOSLASSEN', visual: [12, 12, 12], two: true },
+  { id: 'edge', name: 'Rand-Tap', desc: 'Drei große Zonen. Perfekt für Daumen und Einhandbedienung.', hint: 'RANDZONE ANTIPPEN', visual: [16, 16, 16] },
