/* ============================================================
   6. STORY — seven acts, seventy transmissions
   ============================================================ */
const ACTS = [
  { n: 'I', title: 'ABSTURZ', scene: 'SEKTOR 09 · WRACKFELD', tag: 'Die erste Stimme', color: '#ff5b38' },
  { n: 'II', title: 'DIE STILLE', scene: 'WARTUNGSSCHACHT · UNTEN', tag: 'Etwas hört mit', color: '#44e5da' },
  { n: 'III', title: 'DAS ARCHIV', scene: 'SPEICHERKERN · EBENE 03', tag: 'Die Wahrheit hat Zähne', color: '#ff50be' },
  { n: 'IV', title: 'BLUTPROTOKOLL', scene: 'MEDBAY · QUARANTÄNE', tag: 'Der Körper lügt zuerst', color: '#ff4d6d' },
  { n: 'V', title: 'SCHWARZES LICHT', scene: 'REAKTOR · NULLSEKTOR', tag: 'Glaube frisst Licht', color: '#a35cff' },
  { n: 'VI', title: 'DIE KATHEDRALE', scene: 'HALO-KERN · INNEN', tag: 'Ein Gott mit deiner Stimme', color: '#ff9b40' },
  { n: 'VII', title: 'NULLPUNKT', scene: 'EXTRACTION · LUFTLOS', tag: 'Was bleibt, bist du', color: '#e9ffff' }
];

const STORY = [
  /* ---------------- AKT I — ABSTURZ ---------------- */
  [
    {
      id: 'a1_01', title: 'ERSTER KONTAKT', scene: 'SEKTOR 09 · WRACKFELD', timer: 0,
      msgs: [
        ['S', '…hört mich jemand? Scheiße. {Er} hat gesagt, der Kanal wäre tot. Bitte, wenn da jemand ist: Ich bin in einem Wrack. Ich kann meine Beine nicht sehen.'],
        ['S', 'Mein Name ist {name}. Ich bin {role}, ich bin {age}. Und ich glaube, ich blute. Warum hört sich das so ruhig an?']
      ],
      choices: [
        { t: 'Ich bin hier. Atme. Du bist nicht allein.', h: 'Ruhig bleiben. Vertrauen aufbauen.', eff: { tr: 7, o2: -1, score: 30 }, reply: '…Okay. Okay. Deine Stimme klingt echt. Bitte bleib. Ich hasse diese Stille.' },
        { t: 'Identifiziere dich. Name, Rang, Zugangscode.', h: 'Protokoll vor Mitgefühl.', eff: { sig: 7, tr: -5, score: 20 }, reply: 'Zugangscode? Ich bin gerade aus einem Fenster gefallen, du Arschloch. Aber … hier. Voss, {name}, Kennung 09-Alpha.' },
        { t: 'Ich bin ein Rettungsalgorithmus. Kein Mensch.', h: 'Lüge. Vielleicht ist es leichter.', eff: { tr: -2, sig: 4, score: 15, flag: 'lied_ai' }, reply: 'Ein Algorithmus. Klar. Dann sag deinem Besitzer, dass {sein} Algorithmus verblutet.' }
      ]
    },
    {
      id: 'a1_02', title: 'LEck', scene: 'SEKTOR 09 · WRACKFELD', timer: 0,
      msgs: [
        ['S', 'Ich höre ein Zischen. Mein Helmdisplay sagt O₂ fällt. Die Kabine hinter mir ist offen. Da draußen ist nur … nichts.'],
        ['N', 'KANAL 09 // NEXUS-9 NOTFALLNETZ. Druckabfall in Sektor 09. Empfohlene Maßnahme: Sofortige Versiegelung.']
      ],
      choices: [
        { t: 'Nimm den Schaum aus dem Notfallkasten.', h: 'Risiko: Schaum könnte versagt sein.', risk: .24, eff: { o2: 12, tr: 3, score: 35 }, fail: { o2: -14, vit: -7 }, reply: 'Der Schaum zischt in den Riss. Es hält. Verdammt, es hält tatsächlich.', failReply: 'Der Schaum platzt sofort wieder auf. Ich habe meine Hand auf das Loch gedrückt. Es ist kalt. So kalt.' },
        { t: 'Kriech zum Anzugschrank. Bewegung kostet Sauerstoff.', h: 'Sicherer, aber anstrengend.', eff: { o2: -8, vit: -2, tr: 4, score: 25 }, reply: 'Ich bin im Schrank. Ein alter Bergungsanzug. Er riecht nach totem Kollegen, aber er hält.' },
        { t: 'Bleib still liegen. Ich analysiere die Luft.', h: 'Warte auf das System.', eff: { o2: -5, sig: 8, tr: -2, score: 20 }, reply: 'Still liegen. Während die Luft rausgeht. Du bist ein mieser Therapeut, weißt du das?' }
      ]
    },
    {
