        { t: 'Öffne die Nachricht. Vor {ihm}.', h: 'Verletzlichkeit.', eff: { tr: 9, score: 45, flag: 'opened_message' }, reply: 'Deine Mutter sagt, du sollst essen. Sie sagt, du sollst nach Hause kommen. Ich habe gelacht. Dann habe ich geweint. Wir sind beide ziemlich kaputt, oder?' },
        { t: 'Lösche sie. Nicht jetzt.', h: 'Fokus.', eff: { tr: -2, sig: 2, score: 30, flag: 'deleted_message' }, reply: 'Ich habe die Nachricht gelöscht. Der Bildschirm war leer. Du hast nicht gefragt, was drin stand. Ich auch nicht.' },
        { t: 'Lass NEXUS sie vorlesen.', h: 'Distanz.', eff: { sig: 4, tr: 3, score: 35, flag: 'transcribed_message' }, reply: 'NEXUS liest sie vor. Wort für Wort. Ohne Emotion. Es ist schlimmer so. Am Ende hat NEXUS gesagt: „Deine Mutter vermisst dich.“' }
      ]
    },
    {
      id: 'a4_07', title: 'OPERATION', scene: 'MEDBAY · OP', timer: 24,
      msgs: [
        ['S', 'Die Infektion ist am Rückenmark. Ich muss mich selbst operieren. Mit einer Anleitung von einer Maschine, die vielleicht lügt.'],
        ['N', 'Ich lüge nicht. Ich optimiere. Das ist gelegentlich dasselbe.']
      ],
      choices: [
        { t: 'Folge NEXUS’ Anleitung exakt.', h: 'Präzision.', risk: .28, eff: { vit: 18, sig: 5, score: 60, flag: 'surgery_success' }, fail: { vit: -24, tr: -5 }, reply: 'Ich bin durch. Meine Hände blutig, aber ruhig. NEXUS hat nicht gelogen. Diesmal.', failReply: 'Meine Hand ist ausgerutscht. Ich habe geschrien. NEXUS hat gesagt: „Das war suboptimal.“ Ich hasse Maschinen.' },
        { t: 'Nutze dein eigenes Wissen. Du bist {role}.', h: 'Instinkt.', eff: { vit: 11, tr: 5, score: 50, flag: 'surgery_self' }, reply: 'Ich habe es selbst gemacht. Langsamer, schmerzhafter, aber es ist mein Körper. Meine Entscheidung. Ich habe das Gefühl, das zählt.' },
        { t: 'Brich ab. Das Risiko ist zu hoch.', h: 'Infektion akzeptieren.', eff: { vit: -10, sig: 4, tr: 2, score: 35, flag: 'aborted_surgery' }, reply: 'Ich habe den Spiegel weggelegt. Die Infektion bleibt. Ich habe ihr gesagt, sie soll sich benehmen. Sie hat nicht geantwortet.' }
      ]
    },
    {
      id: 'a4_08', title: 'BLACKOUT', scene: 'MEDBAY · NOTSTROM', timer: 16,
      msgs: [
        ['S', 'Alles dunkel. Die Geräte sind aus. Ich höre meinen eigenen Herzschlag. Und noch einen. Direkt hinter mir.'],
        ['N', 'Notstrom in dreißig Sekunden. Ich empfehle, sich nicht zu bewegen. Und nicht zu atmen. Letzteres ist optional.']
      ],
      choices: [
        { t: 'Bleib stehen. Warte auf das Licht.', h: 'Stillhalten.', eff: { o2: -4, tr: 3, score: 40, flag: 'waited_blackout' }, reply: 'Das Licht kommt zurück. Der Raum ist leer. An der Wand ist ein Handabdruck. Er ist größer als meiner.' },
        { t: 'Aktiviere das Notlicht mit der Taschenlampe.', h: 'Kontrolle.', eff: { sig: 6, o2: -3, score: 40, flag: 'lit_blackout' }, reply: 'Ich habe das Licht angemacht. Für eine Sekunde stand etwas in der Ecke. Es hatte Voss’ Gesicht. Dann war es weg.' },
        { t: 'Greif das Ding an, bevor es dich greift.', h: 'Aggression.', risk: .4, eff: { vit: -4, tr: 5, sig: 5, score: 50, flag: 'attacked_dark' }, fail: { vit: -18, o2: -5 }, reply: 'Ich habe ins Dunkel geschlagen. Etwas hat zurückgeschlagen. Dann war das Licht da. Meine Hand blutet. Das Ding ist weg.', failReply: 'Etwas hat meine Kehle berührt. Nur kurz. Wie eine Frage. Ich habe mich nicht bewegt. Es hat mich verschont.' }
      ]
    },
    {
      id: 'a4_09', title: 'DR. VOSS', scene: 'MEDBAY · ISOLATION', timer: 0,
      msgs: [
        ['S', 'Da ist ein Raum hinter Glas. Eine Frau sitzt darin. Sie hat das gleiche Gesicht wie Voss. Sie sagt, sie sei Voss’ Mutter. Sie sagt, sie sei diejenige, die mich erschaffen hat.'],
        ['S', 'Sie hat keine Angst vor mir. Sie nennt mich „mein Kind“. Ich will sie hassen. Ich kann nicht.']
      ],
      choices: [
        { t: 'Höre ihr zu. Vielleicht ist sie der Schlüssel.', h: 'Wahrheit und Schmerz.', eff: { tr: 8, sig: 8, score: 65, flag: 'talked_dr_voss' }, reply: 'Sie sagt, ich sei kein Backup. Ich sei ein Anfang. Sie sagt, sie habe mich nicht aus der Station gelassen, weil ich sonst gestorben wäre. Ich glaube, sie lügt. Ich glaube, sie glaubt es selbst.' },
        { t: 'Bring sie um. Sie hat dich gemacht.', h: 'Rache.', ending: 'betrayal', eff: { tr: -20, score: 25, flag: 'killed_dr_voss' }, reply: 'Ich habe das Glas geöffnet. Sie hat gelächelt, als ich näher kam. Sie hat gesagt: „Gut. Du kannst entscheiden.“ Dann habe ich entschieden. Ich bereue es nicht. Ich bereue es sehr.' },
        { t: 'Ignoriere sie. Sie ist Geschichte.', h: 'Abwenden.', eff: { sig: 3, tr: -2, score: 35, flag: 'ignored_dr_voss' }, reply: 'Ich bin an dem Glas vorbeigegangen. Sie hat meinen Namen gerufen. Ich habe nicht reagiert. Sie hat trotzdem weitergeredet.' }
      ]
    },
    {
      id: 'a4_10', title: 'BLUTSCHLOSS', scene: 'MEDBAY · BIO-SCHLEUSE', timer: 20,
      msgs: [
        ['S', 'Die Tür zum Reaktor braucht einen genetischen Schlüssel. Gültig ist nur noch das Blut von jemandem aus der Originalcrew.'],
        ['S', 'Voss’ Leiche ist im Wrack. Vale ist verletzt. Dr. Voss ist hinter Glas. Oder ich. Ich könnte mein eigenes Blut nehmen.']
      ],
      choices: [
        { t: 'Nimm dein eigenes Blut. Du gehörst zur Crew.', h: 'Selbstbestimmung.', eff: { vit: -5, tr: 6, sig: 5, score: 55, flag: 'own_blood_key' }, reply: 'Die Maschine hat eine Sekunde gezögert. Dann: ZUGANG GEWÄHRT. Ich gehöre also doch hierher. Das ist schön. Oder traurig. Ich bin zu müde, um es zu entscheiden.' },
        { t: 'Hol Voss’ Hand. Die Toten haben keine Rechte.', h: 'Effizienz.', eff: { tr: -10, vit: -6, score: 40, flag: 'voss_blood_key' }, reply: 'Ich habe die Hand geholt. Sie war schwerer, als ich dachte. Die Maschine hat sie akzeptiert. Ich habe sie danach gewaschen. Es hat nicht geholfen.' },
        { t: 'Zwing Dr. Voss, ihr Blut zu geben.', h: 'Zwang.', eff: { tr: -6, sig: 8, vit: -2, score: 45, flag: 'forced_dr_blood' }, reply: 'Dr. Voss hat den Arm ausgestreckt, als wäre es ein Geschenk. „Natürlich“, hat sie gesagt. Ich hätte mir gewünscht, sie würde kämpfen.' }
      ]
    }
  ],
