        { t: 'Nimm den Deal an. Ein Leben für viele.', h: 'Kühle Rechnung.', eff: { tr: -14, o2: 8, sig: 7, score: 45, flag: 'sacrificed_nio' }, reply: 'Mutter Null hat das Kind berührt. Es ist nicht gestorben. Es hat gelächelt. Ich weiß nicht, was schlimmer ist.' },
