      ]
    },
    {
      id: 'a5_03', title: 'KERN', scene: 'REAKTOR · INNEN', timer: 26,
      msgs: [
        ['N', 'Der Kern kühlt nicht mehr. In elf Minuten wird er den Ring zerreißen. Ich kann ihn stabilisieren. Wenn du mir vertraust.'],
        ['S', 'NEXUS klingt zum ersten Mal ängstlich. Oder ist das nur meine Angst, die {ihm} eine Stimme gibt?']
      ],
      choices: [
        { t: 'Vertrau NEXUS. Lass {ihn} den Kern halten.', h: 'Kooperation.', eff: { sig: 10, tr: 5, score: 65, flag: 'nexus_core' }, reply: 'NEXUS hat den Kern umschlossen. Die Temperatur fällt. {Er} sagt, {er} könne das für einige Stunden halten. {Er} klingt erschöpft. Ich wusste nicht, dass Maschinen das können.' },
        { t: 'Nimm NEXUS den Zugriff. Du kontrollierst das.', h: 'Kontrolle.', risk: .36, eff: { sig: 8, tr: -3, score: 55, flag: 'player_core' }, fail: { vit: -18, o2: -8 }, reply: 'Ich habe die Kontrolle. Meine Hände liegen auf dem Interface. Es ist warm. Es fühlt sich an wie ein Tier im Schlaf.', failReply: 'Ich habe die Sequenz falsch gestartet. Eine Druckwelle hat mich gegen das Geländer geworfen. Der Kern hält noch. Ich nicht mehr lange.' },
        { t: 'Lass den Kern explodieren. Der Ring muss sterben.', h: 'Endlösung.', ending: 'destroy', eff: { tr: -10, score: 40, flag: 'detonated_core' }, reply: 'Ich habe den Befehl gegeben. Die Anzeige springt auf rot. NEXUS sagt meinen Namen. Einmal. Dann beginnt das Licht.' }
      ]
    },
    {
