      choices: [
        { t: 'Das ist Vergangenheit. Wir sind hier. Jetzt.', h: 'Vergebung.', eff: { tr: 12, sig: 3, score: 55, flag: 'forgave_survivor' }, reply: 'Du hast nicht geschrien. Du hast nicht gefragt, warum. Das ist schlimmer als jede Anklage. Danke.' },
        { t: 'Warum hast du mir das nicht früher gesagt?', h: 'Wut.', eff: { tr: 4, sig: 4, score: 45, flag: 'questioned_survivor' }, reply: 'Weil ich Angst hatte, dass du gehst. Und weil ich allein sterben wollte. Beides ist wahr. Ich bin ein feiger Mensch.' },
        { t: 'Ich hätte dich sterben lassen sollen.', h: 'Grausamkeit.', eff: { tr: -12, sig: 5, score: 35, flag: 'threatened_abandon' }, reply: 'Vielleicht. Aber du hast es nicht getan. Also lebst du jetzt mit mir. Das ist die Strafe.' }
      ]
    },
    {
