        { t: 'Schleich vorbei. Nutze den Schatten.', h: 'Stealth.', risk: .22, eff: { o2: -5, tr: 3, score: 50, flag: 'stealth_guards' }, fail: { vit: -14, sig: -5 }, reply: 'Ich bin vorbei. Mein Herz schlägt so laut, dass ich sicher bin, sie hören es.', failReply: 'Einer hat mich gesehen. Ich musste rennen. Er hat geschossen. Die Kugel hat mein Ohr gestreift.' },
