493: .theme-radial .choice-list{height:168px;display:block;margin:0 auto;max-width:330px}
494: .theme-radial .choice-list:before{
495:   content:"";position:absolute;left:50%;top:50%;width:84px;height:84px;transform:translate(-50%,-50%);
496:   border:1px solid rgba(var(--accent-rgb),.18);border-radius:50%;
