502:   font-family:var(--font-mono);font-size:5px;letter-spacing:.18em;color:rgba(var(--accent-rgb),.5);
503: }
504: .theme-radial .choice-btn{
505:   position:absolute;width:112px;min-height:49px;left:50%;top:50%;
506:   transform:translate(-50%,-50%) translate(var(--rx),var(--ry));
507:   padding:5px 7px;border-radius:24px;justify-content:center;
508: }
509: .theme-radial .choice-btn:active{transform:translate(-50%,-50%) translate(var(--rx),var(--ry)) scale(.96)}
510: .theme-radial .choice-btn:nth-child(1){--rx:-106px;--ry:38px}
511: .theme-radial .choice-btn:nth-child(2){--rx:106px;--ry:38px}
512: .theme-radial .choice-btn:nth-child(3){--rx:0;--ry:-62px}
