514: .theme-radial .choice-copy{text-align:center}
515: .theme-radial .choice-copy strong{font-size:8.5px;line-height:1.22}
516: .theme-radial .choice-copy small{display:none}
517: .theme-radial .choice-btn .risk{display:none}
518: .theme-radial .choice-btn .go{display:none}
519: .theme-dual .choice-list{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}
520: .theme-dual .choice-btn{flex-direction:column;justify-content:center;text-align:center;min-height:65px;padding:5px 4px;border-radius:9px}
521: .theme-dual .choice-btn .num{width:16px;height:16px;font-size:6px}
522: .theme-dual .choice-copy strong{font-size:8px;line-height:1.24}
