532: /* notification */
533: #phone-stack{position:absolute;z-index:70;top:calc(var(--safe-top) + 47px);left:10px;right:10px;display:flex;flex-direction:column;gap:5px;pointer-events:none}
534: .phone-notice{
535:   pointer-events:auto;display:flex;gap:8px;align-items:flex-start;padding:8px 9px;
536:   border:1px solid rgba(var(--accent-rgb),.3);border-left:3px solid var(--accent);border-radius:6px;
537:   background:linear-gradient(135deg,rgba(4,20,26,.97),rgba(2,10,14,.98));
538:   box-shadow:0 9px 30px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.05);
539:   animation:noticeIn .45s cubic-bezier(.2,.9,.2,1) both;backdrop-filter:blur(15px);-webkit-backdrop-filter:blur(15px);
540: }
541: .phone-notice.urgent{border-color:rgba(var(--danger-rgb),.5);border-left-color:var(--danger)}
542: .phone-notice.amber{border-color:rgba(var(--amber-rgb),.35);border-left-color:var(--amber)}
543: .phone-notice.leaving{animation:noticeOut .28s ease both}
544: @keyframes noticeIn{from{opacity:0;transform:translateY(-13px) scale(.98)}to{opacity:1;transform:none}}
545: @keyframes noticeOut{to{opacity:0;transform:translateY(-9px) scale(.98)}}
546: .notice-icon{width:25px;height:25px;border-radius:5px;border:1px solid rgba(var(--accent-rgb),.26);display:grid;place-items:center;font-family:var(--font-mono);font-size:8px;color:var(--accent);flex:none;background:rgba(var(--accent-rgb),.07)}
547: .phone-notice.urgent .notice-icon{color:var(--danger);border-color:rgba(var(--danger-rgb),.3);background:rgba(var(--danger-rgb),.07)}
548: .notice-copy{flex:1;min-width:0}
549: .notice-top{display:flex;justify-content:space-between;gap:5px;font-family:var(--font-mono);font-size:5.5px;letter-spacing:.11em;color:var(--muted2);margin-bottom:2px}
550: .notice-top b{color:var(--accent);font-weight:400}
551: .phone-notice.urgent .notice-top b{color:var(--danger)}
552: .notice-copy strong{display:block;font-size:9.5px;line-height:1.3;letter-spacing:.03em}
553: .notice-copy small{display:block;font-size:7.5px;line-height:1.35;color:var(--muted);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
554: .notice-close{font-family:var(--font-mono);font-size:9px;color:var(--muted2);padding:0 1px;flex:none}
