556: /* boot */
557: #boot{position:absolute;inset:0;z-index:200;display:flex;align-items:center;justify-content:center;flex-direction:column;background:#010406;transition:opacity .65s ease,visibility .65s}
558: #boot.hidden{opacity:0;visibility:hidden;pointer-events:none}
559: .boot-grid{position:absolute;inset:0;opacity:.15;background-image:linear-gradient(rgba(var(--accent-rgb),.16) 1px,transparent 1px),linear-gradient(90deg,rgba(var(--accent-rgb),.16) 1px,transparent 1px);background-size:32px 32px;mask-image:radial-gradient(circle at 50% 50%,#000,transparent 72%);-webkit-mask-image:radial-gradient(circle at 50% 50%,#000,transparent 72%)}
560: .boot-logo{position:relative;text-align:center;animation:bootIn .8s cubic-bezier(.2,.8,.2,1) both}
