562: .boot-logo .b-mark{width:38px;height:38px;border:1px solid rgba(var(--accent-rgb),.5);margin:0 auto 20px;transform:rotate(45deg);display:grid;place-items:center;box-shadow:0 0 30px rgba(var(--accent-rgb),.16);animation:bootMark 2.2s ease-in-out infinite}
563: .boot-logo .b-mark:after{content:"";width:12px;height:12px;background:var(--accent);box-shadow:0 0 20px var(--accent)}
564: @keyframes bootMark{0%,100%{box-shadow:0 0 20px rgba(var(--accent-rgb),.1)}50%{box-shadow:0 0 45px rgba(var(--accent-rgb),.32)}}
565: .boot-logo h1{margin:0;font-size:38px;letter-spacing:.08em;line-height:.9;font-weight:900;color:#efffff}
566: .boot-logo h1 span{display:block;font-size:.52em;letter-spacing:.28em;color:var(--accent);-webkit-text-stroke:.5px var(--accent);margin-top:6px}
567: .boot-meta{margin-top:24px;font-family:var(--font-mono);font-size:6.5px;letter-spacing:.22em;color:var(--muted2);text-align:center;line-height:2}
568: .boot-meta b{color:var(--accent);font-weight:400}
569: .boot-bar{width:160px;height:1px;background:rgba(255,255,255,.09);margin:20px auto 0;overflow:hidden}
570: .boot-bar i{display:block;height:100%;width:0;background:var(--accent);box-shadow:0 0 10px var(--accent);animation:bootLoad 2.6s cubic-bezier(.1,.7,.3,1) forwards}
571: @keyframes bootLoad{0%{width:0}35%{width:46%}62%{width:54%}100%{width:100%}}
572: .boot-skip{position:absolute;bottom:calc(var(--safe-bottom) + 24px);font-family:var(--font-mono);font-size:6px;letter-spacing:.2em;color:var(--muted2);animation:liveBlink 2s infinite}
573: .boot-warning{position:absolute;top:calc(var(--safe-top) + 22px);font-family:var(--font-mono);font-size:5.5px;letter-spacing:.2em;color:rgba(var(--danger-rgb),.7);border:1px solid rgba(var(--danger-rgb),.25);padding:4px 7px;border-radius:3px;text-align:center}
