1656:   drawHologram(x, y, scale, t) {
1657:     const ctx = this.ctx, H = this.h;
1658:     const s = Math.max(0.5, Math.min(1.2, H / 780)) * scale * 85;
1659:     const pulse = 1 + Math.sin(t * 1.6) * .006;
