1689:     for (let i = 0; i < 13; i++) {
1690:       const a = t * .35 + i * 2.7, r = .35 + (i % 5) * .11;
1691:       const px = Math.cos(a) * r + (hash(i + 9) - .5) * .2;
1692:       const py = Math.sin(a * 1.3) * .7 - .05;
1693:       ctx.fillStyle = i % 3 === 0 ? 'rgba(255,191,105,.4)' : 'rgba(128,246,255,.35)';
1694:       ctx.fillRect(px, py, .012, .012);
1695:     }
1696:     ctx.restore();
1697:     // base light
1698:     const base = ctx.createRadialGradient(x, y + s * 1.9, 0, x, y + s * 1.9, s * .8);
1699:     base.addColorStop(0, 'rgba(66,221,245,.15)'); base.addColorStop(1, 'rgba(66,221,245,0)');
1700:     ctx.fillStyle = base; ctx.fillRect(x - s, y + s, s * 2, s);
