1706:       { a: '#180b09', b: '#07171c', c: 'rgba(255,91,56,.16)', d: '#ff5b38', e: '#4bd9e8' },
1707:       { a: '#061315', b: '#030b0f', c: 'rgba(68,229,218,.12)', d: '#44e5da', e: '#ffbf69' },
1708:       { a: '#130919', b: '#060b14', c: 'rgba(255,80,190,.13)', d: '#ff50be', e: '#62f6ff' },
1709:       { a: '#17090e', b: '#090b12', c: 'rgba(255,77,109,.15)', d: '#ff4d6d', e: '#ffbf69' },
