1713:     ];
1714:     const p = palettes[clamp(act - 1, 0, 6)];
1715:     const grad = ctx.createLinearGradient(0, 0, 0, H);
1716:     grad.addColorStop(0, p.a); grad.addColorStop(.46, p.b); grad.addColorStop(1, '#010406');
