1655:   }
1656:   drawHologram(x, y, scale, t) {
1657:     const ctx = this.ctx, H = this.h;
1658:     const s = Math.max(0.5, Math.min(1.2, H / 780)) * scale * 85;
1659:     const pulse = 1 + Math.sin(t * 1.6) * .006;
1660:     const flick = (Math.sin(t * 7.4) > -.96 ? 1 : .25) * (Math.sin(t * 1.1) > -.92 ? 1 : .3);
1661:     ctx.save(); ctx.translate(x, y); ctx.scale(s * pulse, s * pulse); ctx.globalAlpha = .78 * flick;
1662:     ctx.globalCompositeOperation = 'screen';
1663:     // body silhouette
1664:     const body = new Path2D();
1665:     body.moveTo(-.58, 1.75); body.lineTo(-.48, .67); body.bezierCurveTo(-.44, .35, -.36, .28, -.22, .22);
1666:     body.lineTo(-.17, .09); body.lineTo(-.24, -.15); body.bezierCurveTo(-.27, -.42, -.15, -.62, 0, -.64);
1667:     body.bezierCurveTo(.19, -.64, .27, -.42, .22, -.12); body.lineTo(.17, .09); body.lineTo(.23, .22);
1668:     body.bezierCurveTo(.41, .3, .49, .44, .55, .78); body.lineTo(.66, 1.75); body.closePath();
1669:     const grad = ctx.createLinearGradient(0, -.8, 0, 1.7);
1670:     grad.addColorStop(0, 'rgba(161,251,255,.32)'); grad.addColorStop(.38, 'rgba(60,203,226,.2)'); grad.addColorStop(1, 'rgba(33,116,146,.035)');
1671:     ctx.fillStyle = grad; ctx.fill(body);
1672:     ctx.strokeStyle = 'rgba(147,250,255,.55)'; ctx.lineWidth = .012; ctx.stroke(body);
1673:     // rim light left/right
1674:     ctx.strokeStyle = 'rgba(255,255,255,.18)'; ctx.lineWidth = .007;
1675:     ctx.beginPath(); ctx.moveTo(-.43, .7); ctx.bezierCurveTo(-.38, .34, -.32, .24, -.19, .18); ctx.stroke();
1676:     // face visor
1677:     ctx.strokeStyle = 'rgba(255,86,133,.55)'; ctx.lineWidth = .018;
1678:     ctx.beginPath(); ctx.moveTo(-.12, -.26); ctx.lineTo(.09, -.25); ctx.stroke();
1679:     // scan lines clipped to body
1680:     ctx.save(); ctx.clip(body);
1681:     for (let yy = -0.6; yy < 1.8; yy += .075) {
1682:       ctx.fillStyle = `rgba(128,246,255,${.025 + .03 * (0.5 + .5 * Math.sin(yy * 18 + t * 5))})`;
1683:       ctx.fillRect(-.7, yy, 1.4, .009);
1684:     }
1685:     const scanY = ((t * .12) % 1.8) - .3;
1686:     ctx.fillStyle = 'rgba(169,255,255,.20)'; ctx.fillRect(-.7, scanY, 1.4, .022);
1687:     ctx.restore();
1688:     // micro particles
1689:     for (let i = 0; i < 13; i++) {
1690:       const a = t * .35 + i * 2.7, r = .35 + (i % 5) * .11;
1691:       const px = Math.cos(a) * r + (hash(i + 9) - .5) * .2;
1692:       const py = Math.sin(a * 1.3) * .7 - .05;
1693:       ctx.fillStyle = i % 3 === 0 ? 'rgba(255,191,105,.4)' : 'rgba(128,246,255,.35)';
1694:       ctx.fillRect(px, py, .012, .012);
1695:     }
1696:     ctx.restore();
1697:     // base light
1698:     const base = ctx.createRadialGradient(x, y + s * 1.9, 0, x, y + s * 1.9, s * .8);
1699:     base.addColorStop(0, 'rgba(66,221,245,.15)'); base.addColorStop(1, 'rgba(66,221,245,0)');
1700:     ctx.fillStyle = base; ctx.fillRect(x - s, y + s, s * 2, s);
1701:   }
1702:   drawCampaign(dt) {
