1713:     ];
1714:     const p = palettes[clamp(act - 1, 0, 6)];
1715:     const grad = ctx.createLinearGradient(0, 0, 0, H);
1716:     grad.addColorStop(0, p.a); grad.addColorStop(.46, p.b); grad.addColorStop(1, '#010406');
1717:     ctx.fillStyle = grad; ctx.fillRect(0, 0, W, H);
1718:     // background glow
1719:     const glow = ctx.createRadialGradient(W * .72, H * .27, 0, W * .72, H * .27, W * .7);
1720:     glow.addColorStop(0, p.c); glow.addColorStop(1, 'rgba(0,0,0,0)');
1721:     ctx.fillStyle = glow; ctx.fillRect(0, 0, W, H);
1722:     // distant window / stars
1723:     if (act === 1 || act === 7) {
1724:       ctx.save(); ctx.beginPath(); ctx.ellipse(W * .28, H * .19, W * .24, H * .09, -.15, 0, TAU); ctx.clip();
1725:       ctx.fillStyle = '#01040a'; ctx.fillRect(0, 0, W, H);
