1406: /* ============================================================
1407:    4. SCENE RENDERER — procedural city / campaign cinematics
1408:    ============================================================ */
1409: class SceneRenderer {
1410:   constructor(canvas) {
1411:     this.canvas = canvas;
1412:     this.ctx = canvas.getContext('2d', { alpha: false });
1413:     this.w = 390; this.h = 694; this.dpr = 1;
1414:     this.mode = 'menu'; this.t = 0; this.last = 0;
1415:     this.menu = { stars: [], rain: [], buildingsFar: [], buildingsMid: [], buildingsNear: [], drones: [], signs: [], flashes: [] };
1416:     this.campaign = { particles: [], sparks: [], rain: [] };
1417:     this.shake = 0;
1418:     this.quality = this.readQuality();
1419:     this.resize();
1420:     if (window.ResizeObserver) new ResizeObserver(() => this.resize()).observe(canvas.parentElement || canvas);
1421:     window.addEventListener('resize', () => this.resize());
1422:     this.loop = this.loop.bind(this);
1423:     requestAnimationFrame(this.loop);
1424:   }
1425:   readQuality() {
1426:     switch (settings.quality) {
1427:       case 'low': return { dpr: 1, rain: 24, stars: 40, particles: 30, glow: false, extras: false, scans: false, city: 0.55 };
1428:       case 'balanced': return { dpr: 1.35, rain: 55, stars: 75, particles: 60, glow: true, extras: false, scans: true, city: 0.78 };
1429:       case 'ultra': return { dpr: 2.5, rain: 190, stars: 180, particles: 180, glow: true, extras: true, scans: true, city: 1.25 };
1430:       default: return { dpr: 1.9, rain: 115, stars: 120, particles: 110, glow: true, extras: true, scans: true, city: 1 };
1431:     }
1432:   }
1433:   refreshQuality() {
1434:     this.quality = this.readQuality();
1435:     this.resize();
1436:     this.buildMenuWorld();
1437:   }
1438:   resize() {
1439:     const rect = (this.canvas.parentElement || this.canvas).getBoundingClientRect();
1440:     const w = Math.max(200, rect.width), h = Math.max(300, rect.height);
1441:     const cap = Math.min(this.quality.dpr, 2.4);
1442:     this.w = w; this.h = h;
1443:     this.dpr = Math.min(cap, Math.max(1, window.devicePixelRatio || 1));
1444:     this.canvas.width = Math.round(w * this.dpr);
1445:     this.canvas.height = Math.round(h * this.dpr);
1446:     this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
1447:     this.buildMenuWorld();
1448:     this.buildCampaignParticles();
1449:   }
1450:   setMode(mode) { this.mode = mode; if (mode === 'menu') this.buildMenuWorld(); }
1451:   buildMenuWorld() {
1452:     const W = this.w, H = this.h, Q = this.quality;
1453:     const rng = mulberry32(9009);
1454:     const m = this.menu;
1455:     m.stars = Array.from({ length: Math.round(Q.stars) }, () => ({
1456:       x: rng() * W, y: rng() * H * .62, r: rng() * 1.2 + .2, a: rng() * .72 + .1, p: rng() * TAU
1457:     }));
1458:     m.rain = Array.from({ length: Math.round(Q.rain) }, () => ({
1459:       x: rng() * W * 1.35 - W * .18, y: rng() * H, len: rng() * 22 + 8, speed: rng() * 420 + 280, a: rng() * .25 + .06
1460:     }));
1461:     const tiers = [
1462:       { key: 'buildingsFar', base: .66, count: Math.round(18 * Q.city), minH: .06, maxH: .17, alpha: .45, col: '#061820' },
1463:       { key: 'buildingsMid', base: .76, count: Math.round(15 * Q.city), minH: .12, maxH: .32, alpha: .8, col: '#04131a' },
1464:       { key: 'buildingsNear', base: .88, count: Math.round(10 * Q.city), minH: .16, maxH: .38, alpha: 1, col: '#020c10' }
1465:     ];
1466:     tiers.forEach(tier => {
1467:       const arr = []; let x = -W * .05;
1468:       while (x < W * 1.08) {
1469:         const bw = (W * .028) + rng() * (W * .085);
1470:         const bh = H * (tier.minH + rng() * (tier.maxH - tier.minH));
1471:         arr.push({ x, w: bw, h: bh, base: H * tier.base, seed: rng() * 9999, antenna: rng() > .62, sign: rng() > .72 });
1472:         x += bw + rng() * W * .012;
1473:       }
1474:       m[tier.key] = arr;
1475:     });
1476:     m.drones = Array.from({ length: Q.extras ? 6 : 3 }, (_, i) => ({
1477:       x: rng() * W, y: H * (.2 + rng() * .34), spd: (rng() - .5) * 12, bob: rng() * TAU, s: .7 + rng() * .8
1478:     }));
1479:     m.signs = [
1480:       { x: W * .12, y: H * .57, text: 'NEXUS', color: '#ff4d6d', rot: -.04 },
1481:       { x: W * .76, y: H * .49, text: 'NULL', color: '#71f6ff', rot: .03 },
1482:       { x: W * .5, y: H * .62, text: 'HILFE', color: '#ffbf69', rot: 0 }
1483:     ];
1484:   }
1485:   buildCampaignParticles() {
1486:     const W = this.w, H = this.h, Q = this.quality, rng = mulberry32(4411);
1487:     this.campaign.particles = Array.from({ length: Q.particles }, () => ({ x: rng() * W, y: rng() * H, r: rng() * 1.6 + .25, vy: -(rng() * 9 + 2), vx: (rng() - .5) * 4, a: rng() * .45 + .08, p: rng() * TAU }));
1488:     this.campaign.sparks = [];
1489:     this.campaign.rain = Array.from({ length: Math.round(Q.rain * .55) }, () => ({ x: rng() * W, y: rng() * H, len: rng() * 18 + 5, s: rng() * 320 + 200, a: rng() * .16 + .03 }));
1490:   }
1491:   loop(now) {
1492:     const dt = Math.min(.05, (now - (this.last || now)) / 1000);
1493:     this.last = now; this.t += dt;
1494:     const ctx = this.ctx;
1495:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
1496:     if (this.mode === 'menu') this.drawMenu(dt);
1497:     else if (this.mode === 'campaign') this.drawCampaign(dt);
1498:     else if (this.mode === 'sandbox') {
1499:       if (window.Sandbox && Sandbox.active) Sandbox.draw(ctx, this.w, this.h, dt, this.t);
1500:       else this.drawMenu(dt, true);
1501:     } else this.drawMenu(dt);
1502:     requestAnimationFrame(this.loop);
1503:   }
1504:   drawMenu(dt, dim = false) {
1505:     const ctx = this.ctx, W = this.w, H = this.h, t = this.t, Q = this.quality, m = this.menu;
1506:     ctx.save();
1507:     if (dim) ctx.globalAlpha = .42;
1508:     // sky
1509:     const sky = ctx.createLinearGradient(0, 0, 0, H * .82);
1510:     sky.addColorStop(0, '#02050c'); sky.addColorStop(.35, '#06121c'); sky.addColorStop(.67, '#0a2027'); sky.addColorStop(1, '#030a0d');
1511:     ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
1512:     // distant aurora
1513:     const aurora = ctx.createRadialGradient(W * .25, H * .2, 0, W * .25, H * .2, W * .7);
1514:     aurora.addColorStop(0, 'rgba(42,164,177,.18)'); aurora.addColorStop(.55, 'rgba(18,71,90,.075)'); aurora.addColorStop(1, 'rgba(0,0,0,0)');
1515:     ctx.fillStyle = aurora; ctx.fillRect(0, 0, W, H * .65);
1516:     const aurora2 = ctx.createRadialGradient(W * .83, H * .3, 0, W * .83, H * .3, W * .5);
1517:     aurora2.addColorStop(0, 'rgba(145,42,96,.12)'); aurora2.addColorStop(1, 'rgba(0,0,0,0)');
1518:     ctx.fillStyle = aurora2; ctx.fillRect(0, 0, W, H * .66);
1519:     // stars
1520:     m.stars.forEach(s => {
1521:       const tw = .3 + .7 * (0.5 + 0.5 * Math.sin(t * 1.3 + s.p));
1522:       ctx.globalAlpha = s.a * tw; ctx.fillStyle = '#bdefff';
1523:       ctx.fillRect(s.x, s.y, s.r, s.r);
1524:     });
1525:     ctx.globalAlpha = 1;
1526:     // orbital ring
1527:     ctx.save();
1528:     ctx.translate(W * .57, H * .15); ctx.rotate(-.22);
1529:     ctx.strokeStyle = 'rgba(112,231,244,.14)'; ctx.lineWidth = 1;
1530:     ctx.beginPath(); ctx.ellipse(0, 0, W * .62, H * .105, 0, 0, TAU); ctx.stroke();
1531:     ctx.strokeStyle = 'rgba(112,231,244,.075)'; ctx.lineWidth = 5;
1532:     ctx.beginPath(); ctx.ellipse(0, 0, W * .62, H * .105, 0, .1, Math.PI * 1.2); ctx.stroke();
1533:     const ringRng = mulberry32(77);
1534:     for (let i = 0; i < 12; i++) {
1535:       const a = ringRng() * TAU;
1536:       const rx = Math.cos(a) * W * .62, ry = Math.sin(a) * H * .105;
1537:       ctx.fillStyle = i % 3 === 0 ? 'rgba(255,191,105,.55)' : 'rgba(113,246,255,.38)';
1538:       ctx.fillRect(rx - 1, ry - 1, 2, 2);
1539:     }
1540:     ctx.restore();
1541:     // orbital debris / ship silhouette
1542:     ctx.save(); ctx.translate(W * .78, H * .22); ctx.globalAlpha = .3; ctx.fillStyle = '#021016';
1543:     ctx.beginPath(); ctx.moveTo(-20, 2); ctx.lineTo(8, -3); ctx.lineTo(24, 1); ctx.lineTo(7, 5); ctx.lineTo(-14, 6); ctx.closePath(); ctx.fill();
1544:     ctx.fillStyle = 'rgba(255,77,109,.55)'; ctx.fillRect(-2, 5, 3, 2); ctx.restore();
1545:     // clouds
1546:     for (let i = 0; i < 4; i++) {
1547:       const cx = ((t * (2.5 + i * 1.1) + i * W * .31) % (W * 1.5)) - W * .25;
1548:       const cy = H * (.18 + i * .1);
1549:       const cloud = ctx.createRadialGradient(cx, cy, 0, cx, cy, W * (.28 + i * .06));
1550:       cloud.addColorStop(0, 'rgba(8,31,41,.2)'); cloud.addColorStop(1, 'rgba(0,0,0,0)');
1551:       ctx.fillStyle = cloud; ctx.fillRect(cx - W * .4, cy - H * .16, W * .8, H * .32);
1552:     }
1553:     // lightning
1554:     if (!m.lastFlash || t - m.lastFlash > 15 + hash(Math.floor(t / 8)) * 12) {
1555:       m.lastFlash = t; m.flashPower = 1;
1556:     }
1557:     if (m.flashPower > 0) {
1558:       m.flashPower -= dt * 1.7;
1559:       ctx.fillStyle = `rgba(147,227,255,${Math.max(0, m.flashPower) * .07})`;
1560:       ctx.fillRect(0, 0, W, H);
1561:     }
1562:     // far city
1563:     this.drawCityLayer(m.buildingsFar, H * .66, 'rgba(4,20,28,.55)', 1.1);
1564:     // glow behind mid
1565:     this.drawCityLayer(m.buildingsMid, H * .76, 'rgba(3,15,21,.88)', 1.35);
1566:     // neon signs
1567:     m.signs.forEach((s, i) => this.drawNeonSign(s, t, i));
1568:     // near city
1569:     this.drawCityLayer(m.buildingsNear, H * .88, 'rgba(1,9,12,1)', 1.7);
1570:     // searchlights
1571:     for (let i = 0; i < 2; i++) {
1572:       const bx = W * (.22 + i * .55), by = H * .76;
1573:       const ang = -.7 + Math.sin(t * .19 + i * 2.1) * .45;
1574:       const grad = ctx.createLinearGradient(bx, by, bx + Math.cos(ang) * H * .7, by + Math.sin(ang) * H * .7);
1575:       grad.addColorStop(0, 'rgba(113,246,255,.075)'); grad.addColorStop(1, 'rgba(113,246,255,0)');
1576:       ctx.save(); ctx.translate(bx, by); ctx.rotate(ang); ctx.fillStyle = grad;
1577:       ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-26, H * .7); ctx.lineTo(26, H * .7); ctx.closePath(); ctx.fill(); ctx.restore();
1578:     }
1579:     // hologram human
1580:     this.drawHologram(W * .78, H * .495, Math.min(W, H) * .0033, t);
1581:     // drones
1582:     m.drones.forEach(d => {
1583:       d.x += d.spd * dt; if (d.x < -20) d.x = W + 20; if (d.x > W + 20) d.x = -20;
1584:       const y = d.y + Math.sin(t * .7 + d.bob) * 5;
1585:       ctx.save(); ctx.translate(d.x, y); ctx.scale(d.s, d.s); ctx.globalAlpha = .65;
1586:       ctx.strokeStyle = 'rgba(170,244,255,.38)'; ctx.lineWidth = .7;
1587:       ctx.beginPath(); ctx.moveTo(-5, 0); ctx.lineTo(0, -3); ctx.lineTo(5, 0); ctx.lineTo(0, 3); ctx.closePath(); ctx.stroke();
1588:       ctx.fillStyle = (Math.sin(t * 5 + d.bob) > .4) ? '#ff4d6d' : 'rgba(255,77,109,.18)';
1589:       ctx.fillRect(-.8, -.8, 1.6, 1.6); ctx.restore();
1590:     });
1591:     // rain
1592:     ctx.lineWidth = .65;
1593:     m.rain.forEach(r => {
1594:       ctx.strokeStyle = `rgba(158,232,247,${r.a})`;
1595:       ctx.beginPath(); ctx.moveTo(r.x, r.y); ctx.lineTo(r.x - r.len * .22, r.y + r.len); ctx.stroke();
1596:       r.y += r.speed * dt; r.x -= r.speed * dt * .22;
1597:       if (r.y > H + 20) { r.y = -20; r.x = Math.random() * W * 1.2; }
1598:       if (r.x < -30) r.x = W + 20;
1599:     });
1600:     // foreground haze
1601:     const haze = ctx.createLinearGradient(0, H * .58, 0, H * .88);
1602:     haze.addColorStop(0, 'rgba(7,27,34,0)'); haze.addColorStop(.6, 'rgba(6,25,32,.3)'); haze.addColorStop(1, 'rgba(1,7,10,.8)');
1603:     ctx.fillStyle = haze; ctx.fillRect(0, H * .55, W, H * .45);
1604:     // scanline-ish light bar
1605:     ctx.globalAlpha = .1;
1606:     const scanY = (t * 22) % H;
1607:     const scan = ctx.createLinearGradient(0, scanY - 20, 0, scanY + 20);
1608:     scan.addColorStop(0, 'rgba(113,246,255,0)'); scan.addColorStop(.5, 'rgba(113,246,255,.4)'); scan.addColorStop(1, 'rgba(113,246,255,0)');
1609:     ctx.fillStyle = scan; ctx.fillRect(0, scanY - 20, W, 40);
1610:     ctx.globalAlpha = 1;
1611:     ctx.restore();
1612:   }
1613:   drawCityLayer(arr, baseY, color, scale) {
1614:     const ctx = this.ctx, W = this.w, H = this.h, t = this.t;
1615:     arr.forEach((b, idx) => {
1616:       const y = baseY - b.h;
1617:       ctx.fillStyle = color;
1618:       ctx.fillRect(b.x, y, b.w, b.h + H);
1619:       // edge light
1620:       ctx.fillStyle = 'rgba(84,209,226,.06)';
1621:       ctx.fillRect(b.x, y, 1, b.h);
1622:       // windows
1623:       const cols = Math.max(1, Math.floor(b.w / 7)), rows = Math.max(2, Math.floor(b.h / 9));
1624:       const wr = mulberry32(Math.floor(b.seed * 1000));
1625:       const count = Math.min(40, Math.floor(cols * rows * .18));
1626:       for (let i = 0; i < count; i++) {
1627:         const wx = b.x + 3 + Math.floor(wr() * cols) * 6;
1628:         const wy = y + 5 + Math.floor(wr() * rows) * 8;
1629:         const flicker = Math.sin(t * (0.5 + wr() * 1.8) + i) > -.84;
1630:         if (!flicker) continue;
1631:         ctx.fillStyle = wr() > .82 ? 'rgba(255,191,105,.5)' : wr() > .5 ? 'rgba(113,246,255,.28)' : 'rgba(125,255,178,.2)';
1632:         ctx.fillRect(wx, wy, 2.2, 1.2);
1633:       }
1634:       if (b.antenna) {
1635:         ctx.strokeStyle = 'rgba(113,246,255,.18)'; ctx.lineWidth = .7;
1636:         ctx.beginPath(); ctx.moveTo(b.x + b.w * .7, y); ctx.lineTo(b.x + b.w * .7, y - 22); ctx.stroke();
1637:         const blink = Math.sin(t * 3 + idx) > .2;
1638:         if (blink) { ctx.fillStyle = 'rgba(255,77,109,.8)'; ctx.fillRect(b.x + b.w * .7 - 1, y - 24, 2, 2); }
1639:       }
1640:       if (b.sign && b.w > 25) {
1641:         const c = idx % 3 === 0 ? 'rgba(255,77,109,.5)' : idx % 3 === 1 ? 'rgba(255,191,105,.45)' : 'rgba(113,246,255,.4)';
1642:         ctx.fillStyle = c; ctx.fillRect(b.x + 3, y + b.h * .28, Math.min(b.w - 6, 14), 1.5);
1643:       }
1644:     });
1645:   }
1646:   drawNeonSign(s, t, i) {
1647:     const ctx = this.ctx;
1648:     const flicker = (Math.sin(t * (2.1 + i) + i * 4) > -.88) ? 1 : .22;
1649:     ctx.save(); ctx.translate(s.x, s.y); ctx.rotate(s.rot); ctx.globalAlpha = flicker;
1650:     ctx.font = '700 9px "Arial Narrow", sans-serif'; ctx.letterSpacing = '2px';
1651:     ctx.fillStyle = s.color; ctx.shadowColor = s.color; ctx.shadowBlur = 12;
1652:     ctx.fillText(s.text, 0, 0);
1653:     ctx.shadowBlur = 0; ctx.strokeStyle = 'rgba(255,255,255,.11)'; ctx.strokeRect(-2, -12, ctx.measureText(s.text).width + 8, 16);
1654:     ctx.restore();
1655:   }
1656:   drawHologram(x, y, scale, t) {
1657:     const ctx = this.ctx, H = this.h;
1658:     const s = Math.max(0.5, Math.min(1.2, H / 780)) * scale * 85;
1659:     const pulse = 1 + Math.sin(t * 1.6) * .006;
1660:     const flick = (Math.sin(t * 7.4) > -.96 ? 1 : .25) * (Math.sin(t * 1.1) > -.92 ? 1 : .3);
1661:     ctx.save(); ctx.translate(x, y); ctx.scale(s * pulse, s * pulse); ctx.globalAlpha = .78 * flick;
1662:     ctx.globalCompositeOperation = 'screen';
