1516:     const aurora2 = ctx.createRadialGradient(W * .83, H * .3, 0, W * .83, H * .3, W * .5);
1517:     aurora2.addColorStop(0, 'rgba(145,42,96,.12)'); aurora2.addColorStop(1, 'rgba(0,0,0,0)');
1518:     ctx.fillStyle = aurora2; ctx.fillRect(0, 0, W, H * .66);
1519:     // stars
1520:     m.stars.forEach(s => {
1521:       const tw = .3 + .7 * (0.5 + 0.5 * Math.sin(t * 1.3 + s.p));
1522:       ctx.globalAlpha = s.a * tw; ctx.fillStyle = '#bdefff';
