1456:       x: rng() * W, y: rng() * H * .62, r: rng() * 1.2 + .2, a: rng() * .72 + .1, p: rng() * TAU
1457:     }));
1458:     m.rain = Array.from({ length: Math.round(Q.rain) }, () => ({
1459:       x: rng() * W * 1.35 - W * .18, y: rng() * H, len: rng() * 22 + 8, speed: rng() * 420 + 280, a: rng() * .25 + .06
1460:     }));
1461:     const tiers = [
