1175: /* ============================================================
1176:    2. AUDIO — fully synthesized, no external assets
1177:    ============================================================ */
1178: class AudioEngine {
1179:   constructor() {
1180:     this.ctx = null; this.master = null; this.musicGain = null; this.sfxGain = null;
1181:     this.mode = 'menu'; this.started = false; this.nodes = []; this.timer = null; this.pulseTimer = null;
1182:     this.noiseBuffer = null;
1183:   }
1184:   init() {
1185:     if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
1186:     const AC = window.AudioContext || window.webkitAudioContext;
1187:     if (!AC) return;
1188:     try {
1189:       this.ctx = new AC();
1190:       this.master = this.ctx.createGain();
1191:       this.master.gain.value = settings.sound ? 0.9 : 0;
1192:       this.master.connect(this.ctx.destination);
1193:       this.musicGain = this.ctx.createGain(); this.musicGain.gain.value = settings.music * 0.24; this.musicGain.connect(this.master);
1194:       this.sfxGain = this.ctx.createGain(); this.sfxGain.gain.value = settings.sfx * 0.5; this.sfxGain.connect(this.master);
1195:       this.noiseBuffer = this.makeNoise(2.4);
1196:       this.started = true;
1197:       this.startAmbient(this.mode);
1198:     } catch (e) { console.warn('Audio unavailable', e); }
1199:   }
1200:   makeNoise(seconds) {
1201:     const len = Math.floor(this.ctx.sampleRate * seconds);
1202:     const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
1203:     const d = buf.getChannelData(0);
1204:     for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
1205:     return buf;
1206:   }
1207:   updateVolumes() {
1208:     if (!this.ctx) return;
1209:     this.master.gain.setTargetAtTime(settings.sound ? 0.9 : 0, this.ctx.currentTime, 0.08);
1210:     this.musicGain.gain.setTargetAtTime(settings.music * 0.24, this.ctx.currentTime, 0.08);
1211:     this.sfxGain.gain.setTargetAtTime(settings.sfx * 0.5, this.ctx.currentTime, 0.06);
1212:   }
1213:   tone(freq, dur, type = 'sine', gain = 0.2, slide = 0, delay = 0, dest = null) {
1214:     if (!this.ctx || !settings.sound) return;
1215:     const t = this.ctx.currentTime + delay;
1216:     const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
1217:     o.type = type; o.frequency.setValueAtTime(Math.max(20, freq), t);
1218:     if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
1219:     g.gain.setValueAtTime(0.0001, t);
1220:     g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.012);
1221:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
1222:     o.connect(g); g.connect(dest || this.sfxGain);
1223:     o.start(t); o.stop(t + dur + 0.03);
1224:   }
1225:   noise(dur = 0.2, gain = 0.2, freq = 800, q = 1, delay = 0) {
1226:     if (!this.ctx || !settings.sound || !this.noiseBuffer) return;
1227:     const t = this.ctx.currentTime + delay;
1228:     const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuffer; src.loop = true;
1229:     const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = freq; f.Q.value = q;
1230:     const g = this.ctx.createGain();
1231:     g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
1232:     src.connect(f); f.connect(g); g.connect(this.sfxGain);
1233:     src.start(t); src.stop(t + dur + 0.02);
1234:   }
1235:   sfx(name) {
1236:     if (!this.ctx || !settings.sound) return;
1237:     switch (name) {
1238:       case 'click': this.tone(620, .06, 'triangle', .1, -180); break;
1239:       case 'back': this.tone(330, .09, 'triangle', .08, 100); break;
1240:       case 'msg': this.tone(880, .1, 'sine', .07); this.tone(1320, .16, 'sine', .045, 0, .08); break;
1241:       case 'notify': this.tone(523, .1, 'triangle', .08); this.tone(784, .12, 'triangle', .07, 0, .08); this.tone(1046, .24, 'sine', .05, 0, .2); break;
1242:       case 'alarm': this.tone(180, .4, 'sawtooth', .08, 90); this.tone(240, .28, 'square', .035, -70, .42); break;
1243:       case 'success': [523, 659, 784, 1046].forEach((f, i) => this.tone(f, .45, 'sine', .075, 0, i * .09)); break;
1244:       case 'error': this.tone(110, .3, 'sawtooth', .1, -35); this.noise(.18, .08, 300, .8); break;
1245:       case 'death': this.tone(90, 1.6, 'sawtooth', .14, -55); this.noise(1.1, .05, 170, .4); break;
1246:       case 'gun': this.noise(.055, .12, 1600, 1.2); this.tone(180, .06, 'square', .05, -60); break;
1247:       case 'rail': this.tone(740, .18, 'sawtooth', .09, -500); this.noise(.12, .08, 2400, 1.6); break;
1248:       case 'hit': this.noise(.06, .08, 900, 2); break;
1249:       case 'explode': this.noise(.45, .22, 280, .7); this.tone(65, .4, 'sawtooth', .12, -30); break;
1250:       case 'pickup': this.tone(660, .09, 'sine', .07, 140); this.tone(990, .18, 'sine', .05, 180, .07); break;
1251:       case 'type': this.tone(1300 + Math.random() * 500, .012, 'square', .012); break;
1252:       case 'glitch': this.noise(.11, .05, 2800, .8); this.tone(75, .13, 'square', .025, 700); break;
1253:       case 'act': [110, 165, 220, 330].forEach((f, i) => this.tone(f, .8, 'sine', .06, 0, i * .12)); break;
1254:       case 'heart': this.tone(52, .14, 'sine', .16); this.tone(48, .12, 'sine', .1, 0, .18); break;
1255:       case 'heal': this.tone(420, .18, 'sine', .07, 240); this.tone(880, .35, 'sine', .045, 220, .1); break;
1256:       default: this.tone(500, .05, 'sine', .04);
1257:     }
1258:   }
1259:   stopAmbient() {
1260:     if (this.timer) { clearInterval(this.timer); this.timer = null; }
1261:     if (this.pulseTimer) { clearInterval(this.pulseTimer); this.pulseTimer = null; }
1262:     this.nodes.forEach(n => { try { n.stop(0); } catch (e) {} try { n.disconnect(); } catch (e) {} });
1263:     this.nodes = [];
1264:   }
1265:   startAmbient(mode) {
1266:     this.mode = mode;
1267:     if (!this.ctx || !settings.sound) return;
1268:     this.stopAmbient();
1269:     const ctx = this.ctx;
1270:     const base = mode === 'combat' ? 46 : mode === 'campaign' ? 38 : 32;
1271:     const root = ctx.createGain(); root.gain.value = 0.0001; root.connect(this.musicGain);
1272:     root.gain.exponentialRampToValueAtTime(mode === 'combat' ? .22 : .15, ctx.currentTime + 1.6);
1273:     this.nodes.push(root);
1274:     const freqs = [base, base * 1.5, base * 2, base * 2.997, base * 4.01];
1275:     freqs.forEach((f, i) => {
1276:       const o = ctx.createOscillator(); const g = ctx.createGain();
1277:       o.type = i === 0 ? 'sawtooth' : i < 3 ? 'triangle' : 'sine';
1278:       o.frequency.value = f; o.detune.value = (i - 2) * (mode === 'combat' ? 8 : 3);
1279:       g.gain.value = i === 0 ? .16 : .05 / (i + .4);
1280:       const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = mode === 'combat' ? 480 : 260; lp.Q.value = 1.2;
1281:       o.connect(g); g.connect(lp); lp.connect(root); o.start(); this.nodes.push(o, g, lp);
1282:     });
1283:     if (mode !== 'combat') {
1284:       const o = ctx.createOscillator(); const g = ctx.createGain();
1285:       o.type = 'sine'; o.frequency.value = 192 - (mode === 'campaign' ? 10 : 0);
1286:       g.gain.value = .028; o.connect(g); g.connect(root); o.start(); this.nodes.push(o, g);
1287:     }
1288:     if (this.noiseBuffer) {
1289:       const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer; src.loop = true;
1290:       const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = mode === 'combat' ? 1200 : 700; f.Q.value = .35;
1291:       const g = ctx.createGain(); g.gain.value = mode === 'combat' ? .035 : .05;
1292:       src.connect(f); f.connect(g); g.connect(this.musicGain); src.start(); this.nodes.push(src, f, g);
1293:     }
1294:     let step = 0;
1295:     const chordSets = mode === 'combat'
1296:       ? [[0, 1, 2.997], [0, 1.335, 2], [0, 1.189, 2.378], [0, 1.498, 2.245]]
1297:       : [[0, 1.5, 2.997], [0, 1.335, 2.245], [0, 1.189, 2.997], [0, 1.414, 2.378]];
1298:     this.timer = setInterval(() => {
1299:       if (!settings.sound || !this.ctx) return;
1300:       const set = chordSets[step % chordSets.length]; step++;
1301:       set.forEach((mult, i) => {
1302:         const o = ctx.createOscillator(); const g = ctx.createGain();
1303:         o.type = i === 0 ? 'triangle' : 'sine'; o.frequency.value = (mode === 'combat' ? 92 : 74) * mult;
1304:         const t = ctx.currentTime;
1305:         g.gain.setValueAtTime(0.0001, t);
1306:         g.gain.exponentialRampToValueAtTime(mode === 'combat' ? .025 : .018, t + .55);
1307:         g.gain.exponentialRampToValueAtTime(0.0001, t + (mode === 'combat' ? 2.4 : 5.8));
1308:         o.connect(g); g.connect(this.musicGain); o.start(t); o.stop(t + 6.2);
1309:       });
1310:     }, mode === 'combat' ? 2500 : 7200);
1311:     if (mode === 'combat') {
1312:       this.pulseTimer = setInterval(() => {
1313:         if (!settings.sound) return;
1314:         this.tone(60, .16, 'sine', .08, -20);
1315:         if (Math.random() > .55) this.noise(.06, .022, 2200, 1.2);
1316:       }, 560);
1317:     } else if (mode === 'campaign') {
1318:       this.pulseTimer = setInterval(() => {
1319:         if (!settings.sound) return;
1320:         this.tone(55, .5, 'sine', .035, -12);
1321:       }, 6200);
1322:     }
1323:   }
1324:   setMode(mode) {
1325:     if (this.mode === mode && this.started) return;
1326:     this.mode = mode;
1327:     if (this.ctx) this.startAmbient(mode);
1328:   }
1329:   setEnabled(on) {
1330:     if (on) { this.init(); if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); }
1331:     settings.sound = on;
1332:     if (this.master) this.master.gain.setTargetAtTime(on ? .9 : 0, this.ctx.currentTime, .08);
1333:   }
1334: }
