2069:         ['N', 'Subjekt 09 zeigt Anzeichen innerer Blutung. Überlebensprognose ohne Intervention: 71 Prozent. Mit Intervention: 94 Prozent. Ich mag Zahlen. Sie lügen nicht.']
2070:       ],
2071:       choices: [
2072:         { t: 'Nimm die Dosis. Du bist wichtiger als deine Vorräte.', h: 'Vitalität jetzt.', eff: { med: -1, vit: 24, tr: 4, score: 35, flag: 'used_med_early' }, reply: 'Es fühlt sich an, als würde warmes Licht durch meine Adern laufen. Danke. Ich hoffe, das war keine Dummheit.' },
2073:         { t: 'Verbinde die Wunde. Spar die Dosis für später.', h: 'Risiko jetzt, Hoffnung später.', eff: { vit: -10, med: 1, tr: 3, score: 30 }, reply: 'Ich habe einen Druckverband gemacht. Es tut höllisch weh, aber ich bin noch da. Der Rest bleibt für später.' },
2074:         { t: 'Gib mir die Kontrolle über das Medikit. Ich entscheide.', h: 'Kontrolle über Ressourcen.', eff: { med: 1, tr: -8, sig: 5, vit: -5, score: 25 }, reply: 'Du willst entscheiden, wann ich Medikamente bekomme? …Okay. Aber wenn ich sterbe, schicke ich dir eine Rechnung in die Hölle.' }
2075:       ]
2076:     },
2077:     {
2078:       id: 'a1_09', title: 'DIE ZWEITE STIMME', scene: 'SEKTOR 09 · ATRIUM', timer: 34,
2079:       msgs: [
2080:         ['V', 'Hier ist Vale. Ich bin im Frachtmodul, Deck 2. Ich stecke fest. Ich habe noch Wasser und einen halben Sauerstofftank. Wer ist da?'],
2081:         ['S', 'Vale lebt? Vale war im zweiten Shuttle. Wenn {er} lebt, heißt das, dass noch mehr von uns übrig sind. Oder dass {er} lügt.']
2082:       ],
2083:       choices: [
2084:         { t: 'Wir holen Vale. Zwei Leben sind besser als eines.', h: 'Hoffnung und Risiko.', eff: { tr: 8, o2: -5, sig: 4, score: 50, flag: 'save_vale' }, reply: 'Dann gehen wir. Vale, halt durch. Wir brauchen dich. Ich glaube, ich brauche dich.' },
2085:         { t: 'Vale ist eine Gefahr. Kontakt abbrechen.', h: 'Misstrauen. Eine Stimme weniger.', eff: { tr: -9, sig: -4, score: 30, flag: 'abandon_vale' }, reply: 'Ich habe den Kanal auf stumm gestellt. Vale hat noch drei Mal meinen Namen gesagt. Beim vierten habe ich das Headset lauter gemacht.' },
2086:         { t: 'Frag Vale nach dem Code für die Rettungskapsel.', h: 'Nutzen, nicht retten.', eff: { sig: 8, tr: -5, score: 40, flag: 'vale_code' }, reply: 'Vale hat den Code. Vale sagt, {er} gibt ihn mir nur, wenn ich {ihn} mitnehme. Verdammte Scheiße.' }
2087:       ]
2088:     },
2089:     {
2090:       id: 'a1_10', title: 'ABSTIEG', scene: 'WARTUNGSSCHACHT · ZUGANG', timer: 0,
2091:       msgs: [
2092:         ['S', 'Der Weg in die Tiefe ist offen. Unter mir nur Dunkelheit und das Ticken von etwas, das keine Uhr sein sollte.'],
2093:         ['N', 'Sektor 10 ist nicht in meiner Karte. Ich empfehle, ihn nicht zu betreten. Ich empfehle außerdem, meinen Empfehlungen nicht immer zu folgen.']
2094:       ],
2095:       choices: [
2096:         { t: 'Steig hinab. Die Kapsel ist unter uns.', h: 'Vorwärts.', eff: { o2: -6, trust: 0, score: 60, flag: 'entered_shaft' }, reply: 'Ich steige. Jede Sprosse singt. Ich hoffe, das ist nur das Metall.' },
2097:         { t: 'Ruh dich kurz aus und iss etwas.', h: 'Vitalität regenerieren, Zeit verlieren.', eff: { vit: 7, o2: -2, tr: 4, score: 30 }, reply: 'Ich habe einen Riegel gegessen, der nach Pappe und Angst schmeckt. Es geht mir besser. Danke.' },
2098:         { t: 'Sichere den Rückweg, bevor du gehst.', h: 'Vorsicht.', eff: { o2: -4, sig: 6, tr: 7, score: 40, flag: 'secured_exit' }, reply: 'Ich habe die Tür verkeilt. Falls wir zurückmüssen. Falls es ein Zurück gibt.' }
2099:       ]
2100:     }
