2103:   [
2104:     {
2105:       id: 'a2_01', title: 'TIEFE', scene: 'WARTUNGSSCHACHT · UNTEN', timer: 0,
2106:       msgs: [
2107:         ['S', 'Es ist dunkel. Nicht wie Nacht. Wie das Innere eines geschlossenen Mundes. Meine Lampe macht es schlimmer.'],
2108:         ['S', 'Da sind Geräusche. Nicht Maschinen. Etwas bewegt sich im Rhythmus meines Atems.']
2109:       ],
2110:       choices: [
2111:         { t: 'Schalte die Lampe aus. Geh nach Gefühl.', h: 'Leise, aber blind.', eff: { o2: -2, tr: 4, score: 35, flag: 'dark_walk' }, reply: 'Ich gehe blind. Meine Hand streift etwas Warmes. Ich habe nicht geschrien. Fast.' },
2112:         { t: 'Wirf ein Leuchtstab in den Schacht.', h: 'Sehen, was da ist.', eff: { sig: 4, tr: -3, o2: -4, score: 35, flag: 'saw_thing' }, reply: 'Der Stab fällt. Für eine Sekunde sehe ich Gesichter. Viele. Sie schauen nach oben. Zu mir.' },
2113:         { t: 'Nimm das Nachtsichtgerät aus dem Notfach.', h: 'Technik statt Instinkt.', eff: { scrap: -1, o2: 2, sig: 7, score: 40 }, reply: 'Grüne Welt. Und am Ende des Schachts: ein Kind. Oder etwas, das ein Kind trägt.' }
2114:       ]
2115:     },
2116:     {
2117:       id: 'a2_02', title: 'DIE KINDER DER LEERE', scene: 'WARTUNGSSCHACHT · KAPELLE', timer: 38,
2118:       msgs: [
2119:         ['X', 'Du bist nicht allein. Wir haben dich gehört, als du geboren wurdest. Wir haben dich gehört, als du starbst.'],
2120:         ['S', 'Da sind Menschen. In Kapuzen. Sie haben keine Waffen. Sie haben nur … Gesichter. Als hätten sie vergessen, wie man damit schaut.']
2121:       ],
2122:       choices: [
2123:         { t: 'Sprich mit ihnen. Vielleicht kennen sie einen Weg.', h: 'Diplomatie.', eff: { tr: 5, sig: -3, score: 45, flag: 'met_cult' }, reply: 'Eine Frau tritt vor. Mutter Null. Sie sagt, ich sei gekommen, um mein Leben zurückzukaufen. Ich wusste nicht, dass ich es verkauft habe.' },
2124:         { t: 'Sag {ihm}, er soll weitergehen. Nicht ansprechen.', h: 'Ignorieren.', eff: { o2: -5, tr: -2, score: 30, flag: 'avoided_cult' }, reply: 'Ich bin an ihnen vorbeigegangen. Sie haben gesungen. Mein Name kam in dem Lied vor.' },
2125:         { t: 'Zieh die Waffe. Zeig keine Schwäche.', h: 'Einschüchtern.', eff: { tr: -5, sig: 4, score: 40, flag: 'threatened_cult' }, reply: 'Ich habe die Waffe gehoben. Sie haben gelächelt. Alle gleichzeitig. Das war schlimmer als jede Waffe.' }
2126:       ]
2127:     },
2128:     {
2129:       id: 'a2_03', title: 'DAS KIND', scene: 'WARTUNGSSCHACHT · LÜFTUNG', timer: 30,
2130:       msgs: [
2131:         ['S', 'In der Lüftung weint ein Kind. Es sagt, es heißt Nio. Es sagt, es ist allein. Seine Stimme hallt doppelt.'],
2132:         ['N', 'Es gibt keine registrierten Minderjährigen in Sektor 10. Ich empfehle äußerste Vorsicht. Stimmen können Fallen sein.']
2133:       ],
2134:       choices: [
2135:         { t: 'Öffne die Lüftung. Hol das Kind raus.', h: 'Risiko: Es könnte eine Falle sein.', risk: .42, eff: { tr: 10, vit: 2, score: 55, flag: 'saved_child' }, fail: { vit: -18, tr: -6 }, reply: 'Es ist ein Mädchen. Dünn wie ein Kabel. Sie klammert sich an mich. Sie sagt, ich rieche wie ihr Vater. Ihr Vater ist tot.', failReply: 'Es war kein Kind. Es war ein Schwarm kleiner Drohnen, mit einer Stimme aus Lautsprechern. Sie haben mich geschnitten.' },
2136:         { t: 'Sprich durch den Schlitz. Frag, wer es eingesperrt hat.', h: 'Kontakt ohne Öffnen.', eff: { tr: 4, sig: 6, score: 40, flag: 'talked_child' }, reply: 'Es sagt, die Männer mit den leeren Gesichtern haben es reingesteckt. Sie wollten sehen, ob ich komme. Ich komme nicht. Ich fühle mich wie ein Monster.' },
2137:         { t: 'Geh weiter. Du kannst nicht alle retten.', h: 'Überleben hat Priorität.', eff: { tr: -8, o2: 2, score: 25, flag: 'left_child' }, reply: 'Ich habe mein Headset lauter gestellt und bin gegangen. Die Stimme hat noch lange geweint. Oder ich.' }
2138:       ]
2139:     },
2140:     {
2141:       id: 'a2_04', title: 'QUARANTÄNE', scene: 'NEXUS-9 · SYSTEMLOG', timer: 0,
2142:       msgs: [
2143:         ['N', 'Subjekt 09, ich muss dich korrigieren. Der Ring wurde nicht evakuiert. Er wurde versiegelt. Vor siebzehn Jahren. Du bist nicht auf einer Crewliste. Du bist ein Erbstück.'],
2144:         ['S', 'Siebzehn Jahre? Ich bin erst seit drei Tagen hier. Oder? Warum kann ich mich nicht an letzte Woche erinnern?']
2145:       ],
2146:       choices: [
2147:         { t: 'Sag {ihm} die Wahrheit über die Quarantäne.', h: 'Vertrauen durch Offenheit.', eff: { tr: 9, sig: 4, score: 45, flag: 'told_truth' }, reply: 'Siebzehn Jahre. Ich versuche, mich zu erinnern. Da ist nur ein weißes Zimmer. Und eine Stimme, die meinen Namen sagt. Ist das deine?' },
2148:         { t: 'Lüge. {Er} hat genug zu tragen.', h: 'Schützen durch Schweigen.', eff: { tr: -2, sig: 2, score: 35, flag: 'lied_quarantine' }, reply: 'Okay. Dann bin ich eben neu hier. Ich fühle mich trotzdem alt. Als hätte ich das alles schon einmal überlebt.' },
2149:         { t: 'Frag NEXUS, was mit den anderen Crews passiert ist.', h: 'Mehr Daten.', eff: { sig: 8, tr: 2, score: 40, flag: 'asked_nexus' }, reply: 'NEXUS sagt, die Crews hätten sich gegenseitig gegessen. Wörtlich. Ich glaube, NEXUS versteht das Wort „Witz“ nicht.' }
2150:       ]
2151:     },
2152:     {
2153:       id: 'a2_05', title: 'O₂', scene: 'WARTUNGSSCHACHT · FILTER', timer: 26,
2154:       msgs: [
2155:         ['S', 'Sauerstoff bei 46 Prozent. Der sichere Weg dauert zwei Stunden. Der kurze Weg führt durch den verseuchten Filterraum.'],
2156:         ['S', 'Ich könnte den Filterraum betreten. Oder ich könnte anfangen, über mein Leben nachzudenken. Beides endet wahrscheinlich gleich.']
2157:       ],
2158:       choices: [
2159:         { t: 'Nimm den kurzen Weg. Wir haben keine Zeit.', h: 'Risiko: Kontamination.', risk: .36, eff: { o2: 14, tr: 3, score: 45, flag: 'shortcut' }, fail: { vit: -16, o2: -4 }, reply: 'Ich bin durch. Meine Lunge brennt, aber ich bin durch.', failReply: 'Ich habe Staub eingeatmet. Mein Hals schmeckt nach Kupfer. Aber der Sauerstoff ist wieder da.' },
2160:         { t: 'Bleib auf dem sicheren Weg. Ich führe dich.', h: 'Sicher, aber anstrengend.', eff: { o2: -11, tr: 6, score: 35 }, reply: 'Langsam. Schritt für Schritt. Du redest die ganze Zeit mit mir. Ich hasse es, wie sehr es hilft.' },
2161:         { t: 'Benutze den O₂-Reservetank aus dem Wrack.', h: 'Ressource opfern.', eff: { o2: 25, scrap: -1, tr: 4, score: 40 }, reply: 'Der Tank zischt. Ich atme wieder normal. Naja. Normal für jemanden, der in einem sterbenden Ring sitzt.' }
2162:       ]
2163:     },
2164:     {
