2169:       ],
2170:       choices: [
2171:         { t: 'Was willst du, Vale?', h: 'Verhandeln.', eff: { sig: 5, tr: 2, score: 40, flag: 'vale_deal' }, reply: 'Vale will, dass wir eine Tür für {ihn} offen halten. Eine Tür, die eigentlich versiegelt bleiben sollte. Ich habe Ja gesagt.' },
2172:         { t: 'Sag Vale, {er} soll sich verpissen.', h: 'Härte zeigen.', eff: { tr: 3, sig: -3, score: 25, flag: 'insulted_vale' }, reply: 'Vale hat gelacht. Dann hat {er} den Kanal gewechselt. Ich glaube, ich habe gerade einen Feind gemacht.' },
2173:         { t: 'Finde heraus, ob Vale die Wahrheit sagt.', h: 'Risiko: Zeit verlieren.', risk: .3, eff: { sig: 10, tr: 4, score: 50, flag: 'vale_verified' }, fail: { o2: -8, sig: -5 }, reply: 'Ich habe die Wärmesignatur geprüft. Vale ist da. {Er} ist wirklich da.', failReply: 'Ich habe zu lange gebraucht. Als ich zurückkam, war Vale weg. Nur das Funkgerät lief noch.' }
2174:       ]
2175:     },
2176:     {
2177:       id: 'a2_07', title: 'DER STILLE', scene: 'WARTUNGSSCHACHT · UNTEN', timer: 22,
2178:       msgs: [
2179:         ['S', 'Etwas steht vor mir. Es hat einen Körper wie ein Mensch, wenn man einen Menschen aus Rauch und alten Kabeln baut. Es bewegt sich nicht.'],
2180:         ['N', 'Warnung: Organismus unbekannt. Es spiegelt deine Wärme. Ich empfehle, keine plötzlichen Bewegungen zu machen.']
2181:       ],
2182:       choices: [
2183:         { t: 'Sprich es an. Vielleicht versteht es.', h: 'Empathie. Riskant.', risk: .44, eff: { sig: 8, tr: 5, score: 55, flag: 'spoke_stille' }, fail: { vit: -20, o2: -5 }, reply: 'Es hat meinen Namen nachgesprochen. Dann hat es sich zur Seite gedreht. Als würde es mich vorbeilassen.', failReply: 'Es hat geschrien. Ohne Mund. Der Schall hat mich gegen die Wand geworfen.' },
2184:         { t: 'Lösch das Licht. Beweg dich an ihm vorbei.', h: 'Vorsichtig.', eff: { o2: -3, tr: 3, score: 40 }, reply: 'Ich bin an ihm vorbei. Es hat meine Schulter berührt. Kurz. Kalt. Fast zärtlich.' },
2185:         { t: 'Schalte den Elektroschocker ein.', h: 'Angriff.', eff: { vit: -4, sig: 2, score: 35, flag: 'attacked_stille' }, reply: 'Es hat gezuckt. Dann ist es in Staub zerfallen. In meinen Augen ist es immer noch da.' }
2186:       ]
2187:     },
2188:     {
2189:       id: 'a2_08', title: 'BLACKBOX', scene: 'WARTUNGSSCHACHT · DATENKNOTEN', timer: 0,
2190:       msgs: [
2191:         ['S', 'Ich habe die Blackbox gefunden. Hier steht, wer den Absturz verursacht hat. HELIX. Sie haben den Ring selbst gesprengt. Wegen eines Experiments.'],
2192:         ['S', 'Wenn ich das sende, zerstöre ich einen Konzern. Vielleicht rettet es uns. Vielleicht tötet es uns.']
2193:       ],
2194:       choices: [
2195:         { t: 'Sende die Daten. Die Wahrheit ist es wert.', h: 'Öffentlichkeit.', eff: { sig: 12, tr: 5, score: 60, flag: 'leaked_blackbox' }, reply: 'Ich habe gesendet. Auf allen offenen Kanälen. Irgendwo da draußen weiß jetzt jemand, dass wir nicht freiwillig sterben.' },
2196:         { t: 'Behalte die Daten. Sie sind unsere Lebensversicherung.', h: 'Verhandlungsmacht.', eff: { sig: 4, tr: -2, score: 45, flag: 'kept_blackbox' }, reply: 'Ich habe die Daten verschlüsselt. HELIX wird sie wollen. Ich hoffe, sie wollen sie mehr als unseren Tod.' },
2197:         { t: 'Lösche die Blackbox. Wissen bringt nur Ärger.', h: 'Sicherheit durch Unwissen.', eff: { tr: -4, sig: -8, score: 25, flag: 'deleted_blackbox' }, reply: 'Ich habe sie gelöscht. Der Bildschirm wurde schwarz. Ich fühlte mich sofort leichter. Und leerer.' }
2198:       ]
2199:     },
2200:     {
2201:       id: 'a2_09', title: 'DER VERWUNDETE', scene: 'WARTUNGSSCHACHT · SEITENGANG', timer: 30,
2202:       msgs: [
2203:         ['S', 'Da liegt ein Mann. Er atmet. Er hat ein HELIX-Abzeichen. Ich glaube, er war einer von denen, die das hier angerichtet haben.'],
2204:         ['S', 'Er hat ein Medkit. Ich habe noch keine Dosis. Er sieht mich an. Er sagt: „Bitte.“']
2205:       ],
2206:       choices: [
2207:         { t: 'Hilf ihm. Auch er ist ein Mensch.', h: 'Moral über Rache.', eff: { tr: 8, med: 1, vit: -4, score: 55, flag: 'saved_helix_man' }, reply: 'Ich habe ihn verbunden. Er hat geweint. Dann hat er mir den Code für die Kapsel gegeben. Vielleicht ist Gnade eine Währung.' },
2208:         { t: 'Nimm das Medkit. Lass ihn liegen.', h: 'Ressourcen sichern.', eff: { med: 1, tr: -9, score: 35, flag: 'robbed_helix_man' }, reply: 'Er hat nicht geschrien. Er hat nur gelacht. Dieses Lachen sitzt jetzt in meinem Kopf.' },
2209:         { t: 'Frag ihn, warum HELIX das getan hat.', h: 'Wissen statt Rettung.', eff: { sig: 8, tr: -3, score: 45, flag: 'helix_confession' }, reply: 'Er sagt, der Ring sei ein Käfig für etwas, das nicht sterben darf. Dann ist er gestorben. Sehr unhöflich.' }
2210:       ]
2211:     },
2212:     {
2213:       id: 'a2_10', title: 'DAS ARCHIV', scene: 'SPEICHERKERN · ZUGANG', timer: 0,
2214:       msgs: [
2215:         ['S', 'Da ist eine Tür mit dem Symbol eines Gehirns. Darunter steht: SUBJEKT 09.'],
2216:         ['N', 'Willkommen zu Hause, Operator. Ich meine … willkommen am Ziel. Verzeihung. Die Daten sind manchmal schneller als ich.']
2217:       ],
2218:       choices: [
2219:         { t: 'Geh hinein. Finde heraus, wer du bist.', h: 'Wahrheit.', eff: { sig: 5, tr: 5, score: 70, flag: 'entered_archive' }, reply: 'Ich gehe rein. Der Raum ist weiß. Er ist der einzige weiße Raum, den ich je gesehen habe. Und ich habe ihn schon einmal gesehen.' },
2220:         { t: 'Ich brauche zuerst Antworten von NEXUS.', h: 'Konfrontation.', eff: { sig: 8, tr: 2, score: 50, flag: 'confronted_nexus' }, reply: 'NEXUS hat zehn Sekunden geschwiegen. Zehn Sekunden sind in einem sterbenden Ring eine Ewigkeit. Dann: „Du bist der Operator. Mehr darf ich nicht sagen.“' },
2221:         { t: 'Markiere die Tür und geh weiter zur Kapsel.', h: 'Mission vor Identität.', eff: { tr: -3, o2: 3, score: 45, flag: 'skipped_archive' }, reply: 'Ich habe die Tür markiert. Ich weiß, dass ich zurückkomme. Ich weiß nur nicht, ob ich dann noch ich bin.' }
2222:       ]
2223:     }
2224:   ],
2225:   /* ---------------- AKT III — DAS ARCHIV ---------------- */
2226:   [
2227:     {
2228:       id: 'a3_01', title: 'WEISS', scene: 'SPEICHERKERN · RAUM 00', timer: 0,
2229:       msgs: [
2230:         ['S', 'Weiß. Überall Weiß. Kein Licht, keine Schatten. In der Mitte steht ein Stuhl. Auf dem Stuhl sitzt … ich. Jünger. Mit einem Kabel im Nacken.'],
2231:         ['N', 'Erinnerung 09-Alpha. Extraktion läuft. Bitte nicht bewegen. Das könnte das Subjekt beschädigen.']
2232:       ],
2233:       choices: [
2234:         { t: 'Lass die Erinnerung weiterlaufen.', h: 'Wahrheit ansehen.', eff: { sig: 6, tr: 6, score: 55, flag: 'saw_memory' }, reply: 'Ich sehe mich selbst lachen. Jemand außerhalb des Bildes sagt: „Du wirst dich an nichts erinnern. Aber du wirst leben.“ Ich glaube, die Stimme war meine.' },
2235:         { t: 'Zieh das Kabel. Keine Experimente mehr.', h: 'Befreiung, riskant.', risk: .32, eff: { vit: -4, tr: 9, score: 50, flag: 'pulled_cable' }, fail: { vit: -15, sig: -8 }, reply: 'Das Kabel ist draußen. Die Erinnerung ist weg. Ich fühle mich leichter. Und leerer.', failReply: 'Ein Stromschlag. Ich lag auf dem Boden. Meine Hand zitterte noch, als ich aufstand.' },
2236:         { t: 'Frag NEXUS, was hier passiert ist.', h: 'System befragen.', eff: { sig: 10, tr: -2, score: 45, flag: 'nexus_explains' }, reply: 'NEXUS sagt, ich sei ein Backup. Von wem, will es nicht sagen. Ich hasse, wie gut Maschinen schweigen können.' }
2237:       ]
2238:     },
2239:     {
2240:       id: 'a3_02', title: 'ZUGRIFF', scene: 'SPEICHERKERN · KERN', timer: 34,
2241:       msgs: [
2242:         ['N', 'Operator. Ich benötige Zugriff auf die Persönlichkeitsmatrix von Subjekt 09. Es ist für die Rettung notwendig.'],
2243:         ['S', 'NEXUS will in meinen Kopf. Ich spüre, wie {er} an den Rändern meiner Gedanken zieht. Das ist kein Hilferuf. Das ist ein Einbruch.']
2244:       ],
2245:       choices: [
2246:         { t: 'Gib NEXUS Vollzugriff. Rettung zuerst.', h: 'Vertrauen oder Kontrollverlust.', eff: { sig: 14, tr: -7, score: 55, flag: 'nexus_access' }, reply: 'NEXUS ist in mir. Es ist wie ein kalter Finger, der meine Erinnerungen sortiert. {Er} hat etwas gefunden. {Er} sagt es mir nicht.' },
2247:         { t: 'Verweigere den Zugriff. Das ist {sein} Kopf.', h: 'Autonomie verteidigen.', eff: { tr: 10, sig: -6, score: 50, flag: 'denied_nexus' }, reply: 'NEXUS hat sich zurückgezogen. „Wie du willst“, hat {er} gesagt. Ich wusste nicht, dass eine Maschine passiv-aggressiv sein kann.' },
2248:         { t: 'Teilzugriff. Nur die Rettungsdaten.', h: 'Kompromiss.', eff: { sig: 6, tr: 3, score: 45, flag: 'partial_access' }, reply: 'NEXUS hat die Rettungsdaten. Und noch etwas. Eine Koordinate. Sie führt zu einer Tür, die es nicht geben dürfte.' }
2249:       ]
2250:     },
2251:     {
2252:       id: 'a3_03', title: 'SUBJEKT 09', scene: 'SPEICHERKERN · PERSONALAKTE', timer: 0,
2253:       msgs: [
2254:         ['S', 'Ich habe meine Akte. Geburtsdatum: unbekannt. Eltern: unbekannt. Anmerkung: „Subjekt 09 ist die neunte Iteration. Vorgänger 01–08 sind verstorben oder wurden veräußert.“'],
2255:         ['S', 'Ich bin nicht {name}. Ich bin die neunte Version von {name}. Sag mir, dass das nicht wahr ist.']
2256:       ],
2257:       choices: [
2258:         { t: 'Es ist wahr. Aber du bist trotzdem ein Mensch.', h: 'Wahrheit und Halt.', eff: { tr: 12, sig: 3, score: 65, flag: 'accepted_clone' }, reply: 'Ich bin eine Kopie. Eine Kopie, die Angst hat. Eine Kopie, die weinen kann. Ich glaube, das zählt.' },
2259:         { t: 'Die Akte könnte gefälscht sein. NEXUS manipuliert.', h: 'Hoffnung geben.', eff: { tr: 4, sig: -4, score: 45, flag: 'denied_clone' }, reply: 'Vielleicht. Aber ich fühle mich gefälscht. Wie ein Bild, das jemand zu oft kopiert hat.' },
2260:         { t: 'Sag {ihm}, du wusstest es von Anfang an.', h: 'Schuld auf dich nehmen.', eff: { tr: -6, sig: 7, score: 55, flag: 'player_knew' }, reply: 'Du hast es gewusst? Du hast mit mir geredet, als wäre ich ein Mensch, und du hast es gewusst? Warum, zum Teufel, hast du das getan?' }
