1665:     body.moveTo(-.58, 1.75); body.lineTo(-.48, .67); body.bezierCurveTo(-.44, .35, -.36, .28, -.22, .22);
1666:     body.lineTo(-.17, .09); body.lineTo(-.24, -.15); body.bezierCurveTo(-.27, -.42, -.15, -.62, 0, -.64);
1667:     body.bezierCurveTo(.19, -.64, .27, -.42, .22, -.12); body.lineTo(.17, .09); body.lineTo(.23, .22);
