1674:     ctx.strokeStyle = 'rgba(255,255,255,.18)'; ctx.lineWidth = .007;
1675:     ctx.beginPath(); ctx.moveTo(-.43, .7); ctx.bezierCurveTo(-.38, .34, -.32, .24, -.19, .18); ctx.stroke();
1676:     // face visor
1677:     ctx.strokeStyle = 'rgba(255,86,133,.55)'; ctx.lineWidth = .018;
1678:     ctx.beginPath(); ctx.moveTo(-.12, -.26); ctx.lineTo(.09, -.25); ctx.stroke();
1679:     // scan lines clipped to body
1680:     ctx.save(); ctx.clip(body);
1681:     for (let yy = -0.6; yy < 1.8; yy += .075) {
1682:       ctx.fillStyle = `rgba(128,246,255,${.025 + .03 * (0.5 + .5 * Math.sin(yy * 18 + t * 5))})`;
1683:       ctx.fillRect(-.7, yy, 1.4, .009);
