1698:     const base = ctx.createRadialGradient(x, y + s * 1.9, 0, x, y + s * 1.9, s * .8);
1699:     base.addColorStop(0, 'rgba(66,221,245,.15)'); base.addColorStop(1, 'rgba(66,221,245,0)');
